using System;
using System.IO;
using System.Text;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value * sign;
        }
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();
        StringBuilder output = new StringBuilder();

        int testCases = scanner.NextInt();

        while (testCases-- > 0)
        {
            int n = scanner.NextInt();
            long[] prefix = new long[n + 1];

            for (int i = 1; i <= n; i++)
                prefix[i] = prefix[i - 1] + scanner.NextInt();

            long answer = 0;

            for (int k = 1; k <= n; k++)
            {
                if (n % k != 0)
                    continue;

                long minimum = long.MaxValue;
                long maximum = long.MinValue;

                for (int end = k; end <= n; end += k)
                {
                    long sum = prefix[end] - prefix[end - k];

                    if (sum < minimum)
                        minimum = sum;
                    if (sum > maximum)
                        maximum = sum;
                }

                long difference = maximum - minimum;
                if (difference > answer)
                    answer = difference;
            }

            output.AppendLine(answer.ToString());
        }

        Console.Write(output.ToString());
    }
}
