using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

public class Program
{
    private static int[] ParseArray(string line)
    {
        MatchCollection matches = Regex.Matches(line, @"-?\d+");
        int[] result = new int[matches.Count];

        for (int i = 0; i < matches.Count; i++)
            result[i] = int.Parse(matches[i].Value);

        return result;
    }

    public static void Main()
    {
        var lines = new List<string>();
        string line;

        while ((line = Console.ReadLine()) != null)
        {
            if (!string.IsNullOrWhiteSpace(line))
                lines.Add(line);
        }

        if (lines.Count < 2)
            return;

        int[] cost = ParseArray(lines[0]);
        int[] time = ParseArray(lines[1]);
        int n = cost.Length;

        const long INF = long.MaxValue / 4;
        long[] dp = new long[n + 1];

        for (int i = 1; i <= n; i++)
            dp[i] = INF;

        for (int i = 0; i < n; i++)
        {
            for (int painted = n - 1; painted >= 0; painted--)
            {
                if (dp[painted] == INF)
                    continue;

                int next = Math.Min(n, painted + time[i] + 1);
                dp[next] = Math.Min(dp[next], dp[painted] + cost[i]);
            }
        }

        Console.WriteLine(dp[n]);
    }
}
