public class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        MatchCollection matches = Regex.Matches(input, @"-?\d+");

        int n = matches.Count;
        if (n == 0)
        {
            Console.WriteLine(0);
            return;
        }

        int[] nums = new int[n];
        int maxValue = 0;

        for (int i = 0; i < n; i++)
        {
            nums[i] = int.Parse(matches[i].Value);
            if (nums[i] > maxValue)
                maxValue = nums[i];
        }

        int[] seen = new int[maxValue + 2];
        long answer = 0;

        for (int left = 0; left < n; left++)
        {
            int stamp = left + 1;
            int distinctCount = 0;
            int imbalance = 0;

            for (int right = left; right < n; right++)
            {
                int value = nums[right];

                if (seen[value] != stamp)
                {
                    if (distinctCount > 0)
                    {
                        imbalance++;

                        if (value > 0 && seen[value - 1] == stamp)
                            imbalance--;

                        if (value + 1 < seen.Length && seen[value + 1] == stamp)
                            imbalance--;
                    }

                    seen[value] = stamp;
                    distinctCount++;
                }

                answer += imbalance;
            }
        }

        Console.WriteLine(answer);
    }
}
