using System;
using System.Collections.Generic;

public class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        if (tokens.Length == 0)
            return;

        int start = 0;
        int count;
        if (int.TryParse(tokens[0], out count) && count == tokens.Length - 1)
            start = 1;

        var words = new List<string>();
        for (int i = start; i < tokens.Length; i++)
            words.Add(tokens[i]);

        if (words.Count == 0)
            return;

        const int Size = 26;
        const int Inf = int.MaxValue / 4;

        int[,] dp = new int[Size, Size];
        int[,] next = new int[Size, Size];

        for (int i = 0; i < Size; i++)
            for (int j = 0; j < Size; j++)
                dp[i, j] = Inf;

        string firstWord = words[0];
        int first = firstWord[0] - 'a';
        int last = firstWord[firstWord.Length - 1] - 'a';
        dp[first, last] = firstWord.Length;

        for (int index = 1; index < words.Count; index++)
        {
            string word = words[index];
            int wordFirst = word[0] - 'a';
            int wordLast = word[word.Length - 1] - 'a';
            int length = word.Length;

            for (int i = 0; i < Size; i++)
                for (int j = 0; j < Size; j++)
                    next[i, j] = Inf;

            for (int left = 0; left < Size; left++)
            {
                for (int right = 0; right < Size; right++)
                {
                    if (dp[left, right] == Inf)
                        continue;

                    int appendCost = dp[left, right] + length -
                                     (right == wordFirst ? 1 : 0);
                    if (appendCost < next[left, wordLast])
                        next[left, wordLast] = appendCost;

                    int prependCost = dp[left, right] + length -
                                      (wordLast == left ? 1 : 0);
                    if (prependCost < next[wordFirst, right])
                        next[wordFirst, right] = prependCost;
                }
            }

            int[,] temp = dp;
            dp = next;
            next = temp;
        }

        int answer = Inf;
        for (int i = 0; i < Size; i++)
            for (int j = 0; j < Size; j++)
                answer = Math.Min(answer, dp[i, j]);

        Console.WriteLine(answer);
    }
}
