        while ((c = input.ReadByte()) != -1)
        {
            if (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                reading = true;
            }
            else if (reading)
            {
                nums.Add(value);
                value = 0;
                reading = false;
            }
        }

        if (reading)
            nums.Add(value);

        if (nums.Count == 0)
            return;

        long current = nums[nums.Count - 1];

        for (int i = nums.Count - 2; i >= 0; i--)
        {
            if (nums[i] <= current)
                current += nums[i];
            else
                current = nums[i];
        }

        Console.WriteLine(current);
    }
