{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        int[] largest = new int[10];
        for (int i = 0; i < largest.Length; i++)
            largest[i] = -1;

        int answer = -1;
        int position = 0;

        while (position < input.Length)
        {
            while (position < input.Length && !char.IsDigit(input[position]))
                position++;

            if (position >= input.Length)
                break;

            int number = 0;
            while (position < input.Length && char.IsDigit(input[position]))
            {
                number = number * 10 + (input[position] - '0');
                position++;
            }

            int value = number;
            int maximumDigit = 0;

            while (value > 0)
            {
                maximumDigit = Math.Max(maximumDigit, value % 10);
                value /= 10;
            }

            if (largest[maximumDigit] != -1)
                answer = Math.Max(answer, largest[maximumDigit] + number);

            if (number > largest[maximumDigit])
                largest[maximumDigit] = number;
        }

        Console.WriteLine(answer);
    }
}
