using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

public class Program
{
    private struct Pair
    {
        public int A;
        public int B;

        public Pair(int a, int b)
        {
            A = a;
            B = b;
        }
    }

    private static int[] ParseNumbers(string line)
    {
        int equalsIndex = line.IndexOf('=');
        if (equalsIndex >= 0)
            line = line.Substring(equalsIndex + 1);

        MatchCollection matches = Regex.Matches(line, @"-?\d+");
        int[] values = new int[matches.Count];

        for (int i = 0; i < matches.Count; i++)
            values[i] = int.Parse(matches[i].Value);

        return values;
    }

    public static void Main()
    {
        List<string> lines = new List<string>();
        string line;

        while ((line = Console.ReadLine()) != null)
        {
            if (!string.IsNullOrWhiteSpace(line))
                lines.Add(line);
        }

        if (lines.Count < 3)
            return;

        int[] nums1 = ParseNumbers(lines[0]);
        int[] nums2 = ParseNumbers(lines[1]);
        int[] xValues = ParseNumbers(lines[2]);

        int n = nums1.Length;
        long x = xValues[0];

        Pair[] pairs = new Pair[n];
        long sum1 = 0;
        long sum2 = 0;

        for (int i = 0; i < n; i++)
        {
            pairs[i] = new Pair(nums1[i], nums2[i]);
            sum1 += nums1[i];
            sum2 += nums2[i];
        }

        Array.Sort(pairs, delegate(Pair p1, Pair p2)
        {
            return p1.B.CompareTo(p2.B);
        });

        long negativeInfinity = long.MinValue / 4;
        long[] dp = new long[n + 1];

        for (int i = 1; i <= n; i++)
            dp[i] = negativeInfinity;

        for (int i = 0; i < n; i++)
        {
            for (int count = i + 1; count >= 1; count--)
            {
                if (dp[count - 1] != negativeInfinity)
                {
                    long reduction = dp[count - 1]
                                   + pairs[i].A
                                   + (long)count * pairs[i].B;

                    if (reduction > dp[count])
                        dp[count] = reduction;
                }
            }
        }

        for (int time = 0; time <= n; time++)
        {
            long minimumSum = sum1 + (long)time * sum2 - dp[time];
            if (minimumSum <= x)
            {
                Console.WriteLine(time);
                return;
            }
        }

        Console.WriteLine(-1);
    }
}
