using System;

public class Program
{
    private static int[] digits;
    private static int divisor;
    private static int offset;
    private static long[,,,] memo;
    private static bool[,,,] visited;

    private static long CountUpTo(long number, int k)
    {
        if (number <= 0)
            return 0;

        string text = number.ToString();
        digits = new int[text.Length];
        for (int i = 0; i < text.Length; i++)
            digits[i] = text[i] - '0';

        divisor = k;
        offset = digits.Length;
        memo = new long[digits.Length + 1, divisor, 2 * digits.Length + 1, 2];
        visited = new bool[digits.Length + 1, divisor, 2 * digits.Length + 1, 2];

        return Dfs(0, 0, 0, false, true);
    }

    private static long Dfs(int position, int remainder, int balance, bool started, bool tight)
    {
        if (position == digits.Length)
            return started && balance == 0 && remainder == 0 ? 1L : 0L;

        int startedIndex = started ? 1 : 0;
        int balanceIndex = balance + offset;

        if (!tight && visited[position, remainder, balanceIndex, startedIndex])
            return memo[position, remainder, balanceIndex, startedIndex];

        int limit = tight ? digits[position] : 9;
        long result = 0;

        for (int digit = 0; digit <= limit; digit++)
        {
            bool nextTight = tight && digit == limit;

            if (!started && digit == 0)
            {
                result += Dfs(position + 1, 0, balance, false, nextTight);
            }
            else
            {
                int nextBalance = balance + (digit % 2 == 0 ? 1 : -1);
                int nextRemainder = (remainder * 10 + digit) % divisor;
                result += Dfs(position + 1, nextRemainder, nextBalance, true, nextTight);
            }
        }

        if (!tight)
        {
            visited[position, remainder, balanceIndex, startedIndex] = true;
            memo[position, remainder, balanceIndex, startedIndex] = result;
        }

        return result;
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        long low = long.Parse(tokens[0]);
        long high = long.Parse(tokens[1]);
        int k = int.Parse(tokens[2]);

        long answer = CountUpTo(high, k) - CountUpTo(low - 1, k);
        Console.WriteLine(answer);
    }
}
