            while (i < input.Length && !char.IsDigit(input[i]))
                i++;

            if (i >= input.Length)
                break;

            long value = 0;
            while (i < input.Length && char.IsDigit(input[i]))
            {
                value = value * 10 + (input[i] - '0');
                i++;
            }

            values[count++] = value;
        }

        long n = values[0];
        long target = values[1];

        long lowCount = Math.Min(n, target / 2);
        long remaining = n - lowCount;

        long lowSum = lowCount * (lowCount + 1) / 2;
        long highSum = remaining * (2 * target + remaining - 1) / 2;

        Console.WriteLine((lowSum % Mod + highSum % Mod) % Mod);
