using System;
using System.Text;

public class Program
{
    public static void Main()
    {
        const long Mod = 12345;

        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        if (tokens.Length == 0)
            return;

        int n = int.Parse(tokens[0]);
        int total = tokens.Length - 1;
        int m = total / n;

        long[] grid = new long[total];
        for (int i = 0; i < total; i++)
            grid[i] = long.Parse(tokens[i + 1]) % Mod;

        int[] result = new int[total];

        long prefix = 1;
        for (int i = 0; i < total; i++)
        {
            result[i] = (int)prefix;
            prefix = (prefix * grid[i]) % Mod;
        }

        long suffix = 1;
        for (int i = total - 1; i >= 0; i--)
        {
            result[i] = (int)((result[i] * suffix) % Mod);
            suffix = (suffix * grid[i]) % Mod;
        }

        StringBuilder output = new StringBuilder();
        output.AppendLine(n.ToString());

        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < m; j++)
            {
                if (j > 0)
                    output.Append(' ');

                output.Append(result[i * m + j]);
            }

            if (i + 1 < n)
                output.AppendLine();
        }

        Console.Write(output.ToString());
    }
}
