using System;
using System.Collections.Generic;

public class Program
{
    private static List<long> ParseNumbers(string line)
    {
        var numbers = new List<long>();
        long value = 0;
        bool reading = false;
        bool negative = false;

        for (int i = 0; i <= line.Length; i++)
        {
            char c = i < line.Length ? line[i] : ' ';

            if (c == '-' && !reading)
            {
                negative = true;
            }
            else if (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                reading = true;
            }
            else if (reading)
            {
                numbers.Add(negative ? -value : value);
                value = 0;
                reading = false;
                negative = false;
            }
            else
            {
                negative = false;
            }
        }

        return numbers;
    }

    public static void Main()
    {
        var lines = new List<string>();
        string line;

        while ((line = Console.ReadLine()) != null)
        {
            if (!string.IsNullOrWhiteSpace(line))
                lines.Add(line);
        }

        if (lines.Count < 2)
            return;

        List<long> parsedNums = ParseNumbers(lines[0]);
        List<long> parsedTarget = ParseNumbers(lines[1]);

        if (parsedNums.Count == 0 || parsedTarget.Count == 0)
            return;

        int n = parsedNums.Count;
        long[] nums = parsedNums.ToArray();
        long target = parsedTarget[0];

        long total = 0;
        for (int i = 0; i < n; i++)
            total += nums[i];

        long completeCycles = target / total;
        long remainder = target % total;

        if (remainder == 0)
        {
            Console.WriteLine(completeCycles * n);
            return;
        }

        long windowSum = 0;
        int left = 0;
        int shortest = int.MaxValue;

        for (int right = 0; right < 2 * n; right++)
        {
            windowSum += nums[right % n];

            while (left <= right && windowSum > remainder)
            {
                windowSum -= nums[left % n];
                left++;
            }

            if (windowSum == remainder)
            {
                int length = right - left + 1;
                if (length < shortest)
                    shortest = length;
            }
        }

        if (shortest == int.MaxValue)
            Console.WriteLine(-1);
        else
            Console.WriteLine(completeCycles * n + shortest);
    }
}
