        string[] lines = input.Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);

        if (lines.Length < 2)
            return;

        int[] nums1 = ParseArray(lines[0]);
        int[] nums2 = ParseArray(lines[1]);

        if (nums1.Length != nums2.Length || nums1.Length == 0)
        {
            Console.WriteLine(-1);
            return;
        }

        int withoutLastSwap = CountOperations(nums1, nums2, false);
        int withLastSwap = CountOperations(nums1, nums2, true);

        int answer;
        if (withoutLastSwap == -1)
            answer = withLastSwap;
        else if (withLastSwap == -1)
            answer = withoutLastSwap;
        else
            answer = Math.Min(withoutLastSwap, withLastSwap);

        Console.WriteLine(answer);
    }

    private static int CountOperations(int[] nums1, int[] nums2, bool swapLast)
    {
        int n = nums1.Length;
        int max1 = swapLast ? nums2[n - 1] : nums1[n - 1];
        int max2 = swapLast ? nums1[n - 1] : nums2[n - 1];
        int operations = swapLast ? 1 : 0;

        for (int i = 0; i < n - 1; i++)
        {
            bool validWithoutSwap = nums1[i] <= max1 && nums2[i] <= max2;
            bool validWithSwap = nums2[i] <= max1 && nums1[i] <= max2;

            if (validWithoutSwap)
                continue;

            if (validWithSwap)
                operations++;
            else
                return -1;
        }

        return operations;
    }

    private static int[] ParseArray(string line)
    {
        MatchCollection matches = Regex.Matches(line, @"-?\d+");
        List<int> values = new List<int>();

        foreach (Match match in matches)
            values.Add(int.Parse(match.Value));

        return values.ToArray();
    }
