using System;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly TextReader reader = Console.In;
        private readonly char[] buffer = new char[4096];
        private int length;
        private int position;

        public string Next()
        {
            while (true)
            {
                if (position >= length)
                {
                    length = reader.Read(buffer, 0, buffer.Length);
                    position = 0;
                    if (length == 0)
                        return null;
                }

                if (!char.IsWhiteSpace(buffer[position]))
                    break;

                position++;
            }

            var result = new System.Text.StringBuilder();

            while (true)
            {
                if (position >= length)
                {
                    length = reader.Read(buffer, 0, buffer.Length);
                    position = 0;
                    if (length == 0)
                        break;
                }

                char c = buffer[position];
                if (char.IsWhiteSpace(c))
                    break;

                result.Append(c);
                position++;
            }

            return result.ToString();
        }

        public int NextInt()
        {
            return int.Parse(Next());
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        string word = scanner.Next();

        if (string.IsNullOrEmpty(word))
        {
            Console.WriteLine(0);
            return;
        }

        int k = scanner.NextInt();
        int n = word.Length;
        long answer = 0;

        int[] frequencies = new int[26];
        int[] stamps = new int[26];
        int epoch = 0;

        int maxDistinct = Math.Min(26, n / k);

        for (int distinct = 1; distinct <= maxDistinct; distinct++)
        {
            int windowLength = distinct * k;
            int left = 0;
            int exactlyK = 0;
            epoch++;

            for (int right = 0; right < n; right++)
            {
                if (right > 0 &&
                    Math.Abs((word[right] - 'a') - (word[right - 1] - 'a')) > 2)
                {
                    epoch++;
                    exactlyK = 0;
                    left = right;
                }

                int added = word[right] - 'a';
                if (stamps[added] != epoch)
                {
                    stamps[added] = epoch;
                    frequencies[added] = 0;
                }

                if (frequencies[added] == k)
                    exactlyK--;

                frequencies[added]++;

                if (frequencies[added] == k)
                    exactlyK++;

                if (right - left + 1 > windowLength)
                {
                    int removed = word[left] - 'a';

                    if (frequencies[removed] == k)
                        exactlyK--;

                    frequencies[removed]--;

                    if (frequencies[removed] == k)
                        exactlyK++;

                    left++;
                }

                if (right - left + 1 == windowLength && exactlyK == distinct)
                    answer++;
            }
        }

        Console.WriteLine(answer);
    }
}
