            return 0;

        long result = 1 % modulus;
        baseValue %= modulus;

        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = (result * baseValue) % modulus;

            baseValue = (baseValue * baseValue) % modulus;
            exponent >>= 1;
        }

        return result;
    }

