using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

public class Program
{
    private static int target;
    private static readonly Dictionary<int, int> memo = new Dictionary<int, int>();
    private static readonly int[] divisors = { 5, 11 };

    private static int Solve(int value)
    {
        if (value <= target)
            return target - value;

        int cached;
        if (memo.TryGetValue(value, out cached))
            return cached;

        int best = value - target;

        foreach (int divisor in divisors)
        {
            int remainder = value % divisor;
            int quotient = value / divisor;

            int adjustDown = remainder + 1 + Solve(quotient);
            best = Math.Min(best, adjustDown);

            if (remainder != 0)
            {
                int adjustUp = divisor - remainder + 1 + Solve(quotient + 1);
                best = Math.Min(best, adjustUp);
            }
        }

        memo[value] = best;
        return best;
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        MatchCollection matches = Regex.Matches(input, @"\d+");

        if (matches.Count < 2)
            return;

        int x = int.Parse(matches[0].Value);
        target = int.Parse(matches[1].Value);

        Console.WriteLine(Solve(x));
    }
