            int value = int.Parse(tokens[i]);
            if (IsPrime(value))
            {
                if (firstPrimeIndex == -1)
                    firstPrimeIndex = i;

                lastPrimeIndex = i;
            }
        }

        Console.WriteLine(lastPrimeIndex - firstPrimeIndex);
    }
}
