    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<int> values = ParseIntegers(input);

        if (values.Count < 2)
            return;

        int n = values.Count - 1;
        int k = values[n];
        long[] dp = new long[n];
        long answer = long.MinValue;

        for (int i = n - 1; i >= 0; i--)
        {
            dp[i] = values[i];

            if (i + k < n)
                dp[i] += dp[i + k];

            if (dp[i] > answer)
                answer = dp[i];
        }

        Console.WriteLine(answer);
    }

    private static List<int> ParseIntegers(string input)
    {
        var result = new List<int>();
        int i = 0;

        while (i < input.Length)
        {
            while (i < input.Length && input[i] != '-' && !char.IsDigit(input[i]))
                i++;

            if (i >= input.Length)
                break;

            int sign = 1;
            if (input[i] == '-')
            {
                sign = -1;
                i++;
            }

            int value = 0;
            bool hasDigit = false;

            while (i < input.Length && char.IsDigit(input[i]))
            {
                hasDigit = true;
                value = value * 10 + (input[i] - '0');
                i++;
            }

            if (hasDigit)
                result.Add(value * sign);
        }

        return result;
    }
