public class Program
{
    private const long Mod = 1000000007L;

    public static void Main()
    {
        string[] input = Console.In.ReadToEnd()
            .Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        int zero = int.Parse(input[0]);
        int one = int.Parse(input[1]);
        int limit = int.Parse(input[2]);

        long[,] endWithZero = new long[zero + 1, one + 1];
        long[,] endWithOne = new long[zero + 1, one + 1];

        for (int i = 0; i <= zero; i++)
        {
            for (int j = 0; j <= one; j++)
            {
                if (i > 0)
                {
                    if (j == 0)
                    {
                        endWithZero[i, j] = i <= limit ? 1 : 0;
                    }
                    else
                    {
                        long value = endWithZero[i - 1, j] + endWithOne[i - 1, j];

                        int removedIndex = i - limit - 1;
                        if (removedIndex >= 0)
                            value -= endWithOne[removedIndex, j];

                        endWithZero[i, j] = (value % Mod + Mod) % Mod;
                    }
                }

                if (j > 0)
                {
                    if (i == 0)
                    {
                        endWithOne[i, j] = j <= limit ? 1 : 0;
                    }
                    else
                    {
                        long value = endWithOne[i, j - 1] + endWithZero[i, j - 1];

                        int removedIndex = j - limit - 1;
                        if (removedIndex >= 0)
                            value -= endWithZero[i, removedIndex];

                        endWithOne[i, j] = (value % Mod + Mod) % Mod;
                    }
                }
            }
        }

        long answer = (endWithZero[zero, one] + endWithOne[zero, one]) % Mod;
        Console.WriteLine(answer);
    }
}
