        powers.Sort();

        long[] values = new long[powers.Count];
        long[] totalDamage = new long[powers.Count];
        int uniqueCount = 0;

        foreach (long power in powers)
        {
            if (uniqueCount == 0 || values[uniqueCount - 1] != power)
            {
                values[uniqueCount] = power;
                totalDamage[uniqueCount] = power;
                uniqueCount++;
            }
            else
            {
                totalDamage[uniqueCount - 1] += power;
            }
        }

        long[] dp = new long[uniqueCount];
        int firstConflicting = 0;

        for (int i = 0; i < uniqueCount; i++)
        {
            while (firstConflicting < i &&
                   values[firstConflicting] < values[i] - 2)
            {
                firstConflicting++;
            }

            long take = totalDamage[i];
            if (firstConflicting > 0)
                take += dp[firstConflicting - 1];

            long skip = i > 0 ? dp[i - 1] : 0;
            dp[i] = Math.Max(take, skip);
        }

        Console.WriteLine(dp[uniqueCount - 1]);
    }

    private static List<long> ParseNumbers(string input)
    {
