using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value * sign;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }
    }

    private static List<int>[] ReadTree(FastScanner scanner)
    {
        int edgeCount = scanner.NextInt();
        int nodeCount = edgeCount + 1;

        var graph = new List<int>[nodeCount];
        for (int i = 0; i < nodeCount; i++)
            graph[i] = new List<int>();

        for (int i = 0; i < edgeCount; i++)
        {
            int a = scanner.NextInt();
            int b = scanner.NextInt();
            graph[a].Add(b);
            graph[b].Add(a);
        }

        return graph;
    }

    private static int FindFarthest(List<int>[] graph, int start, out int farthestNode)
    {
        int n = graph.Length;
        int[] nodeStack = new int[n];
        int[] parentStack = new int[n];
        int[] depthStack = new int[n];
        int top = 0;

        nodeStack[top] = start;
        parentStack[top] = -1;
        depthStack[top] = 0;
        top++;

        farthestNode = start;
        int maxDepth = 0;

        while (top > 0)
        {
            top--;
            int node = nodeStack[top];
            int parent = parentStack[top];
            int depth = depthStack[top];

            if (depth > maxDepth)
            {
                maxDepth = depth;
                farthestNode = node;
            }

            foreach (int next in graph[node])
            {
                if (next == parent)
                    continue;

                nodeStack[top] = next;
                parentStack[top] = node;
                depthStack[top] = depth + 1;
                top++;
            }
        }

        return maxDepth;
    }

    private static int GetDiameter(List<int>[] graph)
    {
        int farthest;
        FindFarthest(graph, 0, out farthest);

        int otherEnd;
        return FindFarthest(graph, farthest, out otherEnd);
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        List<int>[] tree1 = ReadTree(scanner);
        List<int>[] tree2 = ReadTree(scanner);

        int diameter1 = GetDiameter(tree1);
        int diameter2 = GetDiameter(tree2);

        int radius1 = (diameter1 + 1) / 2;
        int radius2 = (diameter2 + 1) / 2;
        int connectedDiameter = radius1 + radius2 + 1;

        int answer = Math.Max(Math.Max(diameter1, diameter2), connectedDiameter);
        Console.WriteLine(answer);
    }
}
