```csharp
using System;
using System.IO;

public class Program
{
    private struct Circle
    {
        public long X;
        public long Y;
        public long R;

        public Circle(long x, long y, long r)
        {
            X = x;
            Y = y;
            R = r;
        }
    }

    private sealed class DisjointSet
    {
        private readonly int[] parent;
        private readonly byte[] rank;

        public DisjointSet(int size)
        {
            parent = new int[size];
            rank = new byte[size];

            for (int i = 0; i < size; i++)
                parent[i] = i;
        }

        public int Find(int x)
        {
            int root = x;
            while (parent[root] != root)
                root = parent[root];

            while (parent[x] != x)
            {
                int next = parent[x];
                parent[x] = root;
                x = next;
            }

            return root;
        }

        public void Union(int a, int b)
        {
            int rootA = Find(a);
            int rootB = Find(b);

            if (rootA == rootB)
                return;

            if (rank[rootA] < rank[rootB])
            {
                parent[rootA] = rootB;
            }
            else if (rank[rootA] > rank[rootB])
            {
                parent[rootB] = rootA;
            }
            else
            {
                parent[rootB] = rootA;
                rank[rootA]++;
            }
        }
    }

    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            long sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value * sign;
        }
    }

    private static bool IntersectsVerticalSegment(
        Circle circle, long sideX, long segmentBottom, long segmentTop)
    {
        long dx = circle.X - sideX;
        if (dx < 0) dx = -dx;

        long dy = 0;
        if (circle.Y < segmentBottom)
            dy = segmentBottom - circle.Y;
        else if (circle.Y > segmentTop)
            dy = circle.Y - segmentTop;

        return dx * dx + dy * dy <= circle.R * circle.R;
    }

    private static bool IntersectsHorizontalSegment(
        Circle circle, long sideY, long segmentLeft, long segmentRight)
    {
        long dy = circle.Y - sideY;
        if (dy < 0) dy = -dy;

        long dx = 0;
        if (circle.X < segmentLeft)
            dx = segmentLeft - circle.X;
        else if (circle.X > segmentRight)
            dx = circle.X - segmentRight;

        return dx * dx + dy * dy <= circle.R * circle.R;
    }

    private static bool ShouldConnect(
        Circle a, Circle b, long xCorner, long yCorner)
    {
        long dx = a.X - b.X;
        long dy = a.Y - b.Y;
        long sumR = a.R + b.R;

        if (dx * dx + dy * dy > sumR * sumR)
            return false;

        long weightedX = a.X * b.R + b.X * a.R;
        long weightedY = a.Y * b.R + b.Y * a.R;

        return weightedX >= 0 &&
               weightedY >= 0 &&
               weightedX <= xCorner * sumR &&
               weightedY <= yCorner * sumR;
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();

        long xCorner = scanner.NextLong();
        long yCorner = scanner.NextLong();
        int n = (int)scanner.NextLong();

        Circle[] circles = new Circle[n];
        for (int i = 0; i < n; i++)
        {
            long x = scanner.NextLong();
            long y = scanner.NextLong();
            long r = scanner.NextLong();
            circles[i] = new Circle(x, y, r);
        }

        int leftTopBoundary = n;
        int bottomRightBoundary = n + 1;
        DisjointSet dsu = new DisjointSet(n + 2);

        for (int i = 0; i < n; i++)
        {
            Circle circle = circles[i];

            bool touchesLeft =
                IntersectsVerticalSegment(circle, 0, 0, yCorner);
            bool touchesTop =
                IntersectsHorizontalSegment(circle, yCorner, 0, xCorner);

            bool touchesBottom =
                IntersectsHorizontalSegment(circle, 0, 0, xCorner);
            bool touchesRight =
                IntersectsVerticalSegment(circle, xCorner, 0, yCorner);

            if (touchesLeft || touchesTop)
                dsu.Union(i, leftTopBoundary);

            if (touchesBottom || touchesRight)
                dsu.Union(i, bottomRightBoundary);
        }

        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                if (ShouldConnect(circles[i], circles[j], xCorner, yCorner))
                    dsu.Union(i, j);
            }
        }

        bool reachable =
            dsu.Find(leftTopBoundary) != dsu.Find(bottomRightBoundary);

        Console.WriteLine(reachable ? "true" : "false");
    }
}
