        if (input.Length == 0)
        {
            Console.WriteLine(0);
            return;
        }

        string[] tokens = input.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);
        string s = tokens[0];
        int n = s.Length;

        List<int> zeroPositions = new List<int>();
        for (int i = 0; i < n; i++)
        {
            if (s[i] == '0')
                zeroPositions.Add(i);
        }

        long answer = 0;
        int firstZeroIndex = 0;

        for (int start = 0; start < n; start++)
        {
            while (firstZeroIndex < zeroPositions.Count &&
                   zeroPositions[firstZeroIndex] < start)
            {
                firstZeroIndex++;
            }

            int firstZeroPosition = firstZeroIndex < zeroPositions.Count
                ? zeroPositions[firstZeroIndex]
                : n;

            // Substrings containing no zeros.
            answer += firstZeroPosition - start;

            int remainingLength = n - start;

            // Substrings containing exactly zeroCount zeros.
            for (int zeroCount = 1;
                 zeroCount * zeroCount + zeroCount <= remainingLength;
                 zeroCount++)
            {
                int lastZeroIndex = firstZeroIndex + zeroCount - 1;
                if (lastZeroIndex >= zeroPositions.Count)
                    break;

                int lastZeroPosition = zeroPositions[lastZeroIndex];
                int nextZeroPosition = lastZeroIndex + 1 < zeroPositions.Count
                    ? zeroPositions[lastZeroIndex + 1]
                    : n;

                int requiredEnd = start + zeroCount * zeroCount + zeroCount - 1;
                int minimumEnd = Math.Max(lastZeroPosition, requiredEnd);

                if (minimumEnd < nextZeroPosition)
                    answer += nextZeroPosition - minimumEnd;
            }
        }

        Console.WriteLine(answer);
    }
}
