using System.IO;

public class Program
{
    public static void Main()
    {
        List<long> values = ReadAllNumbers();
        if (values.Count < 2)
            return;

        int mountainHeight = (int)values[0];
        long minWorkerTime = long.MaxValue;
        long[] workerTimes = new long[values.Count - 1];

        for (int i = 1; i < values.Count; i++)
        {
            workerTimes[i - 1] = values[i];
            if (values[i] < minWorkerTime)
                minWorkerTime = values[i];
        }

        long low = 0;
        long high = minWorkerTime * mountainHeight * (mountainHeight + 1L) / 2L;

        while (low < high)
        {
            long mid = low + (high - low) / 2;

            if (CanFinish(mid, mountainHeight, workerTimes))
                high = mid;
            else
                low = mid + 1;
        }

        Console.WriteLine(low);
    }

    private static bool CanFinish(long time, int mountainHeight, long[] workerTimes)
    {
        long totalReduced = 0;

        foreach (long workerTime in workerTimes)
        {
            int left = 0;
            int right = mountainHeight;

            while (left < right)
            {
                int mid = left + (right - left + 1) / 2;
                long requiredTime = workerTime * mid * (mid + 1L) / 2L;

                if (requiredTime <= time)
                    left = mid;
                else
                    right = mid - 1;
            }

            totalReduced += left;
            if (totalReduced >= mountainHeight)
                return true;
        }

        return false;
    }

    private static List<long> ReadAllNumbers()
    {
        byte[] data = ReadAllBytes(Console.OpenStandardInput());
        List<long> numbers = new List<long>();
        long value = 0;
        bool reading = false;

        for (int i = 0; i < data.Length; i++)
        {
            byte c = data[i];

            if (c >= (byte)'0' && c <= (byte)'9')
            {
                value = value * 10 + (c - (byte)'0');
                reading = true;
            }
            else if (reading)
            {
                numbers.Add(value);
                value = 0;
                reading = false;
            }
        }

        if (reading)
            numbers.Add(value);

        return numbers;
    }

    private static byte[] ReadAllBytes(Stream stream)
    {
        using (MemoryStream memory = new MemoryStream())
        {
            byte[] buffer = new byte[8192];
            int read;

            while ((read = stream.Read(buffer, 0, buffer.Length)) > 0)
                memory.Write(buffer, 0, read);

            return memory.ToArray();
        }
    }
}
