        string secondLine = ReadNonEmptyLine();

        if (firstLine == null || secondLine == null)
            return;

        long[] energyDrinkA = ParseArray(firstLine);
        long[] energyDrinkB = ParseArray(secondLine);

        int n = Math.Min(energyDrinkA.Length, energyDrinkB.Length);
        if (n == 0)
        {
            Console.WriteLine(0);
            return;
        }

        long[] dpA = new long[n];
        long[] dpB = new long[n];

        dpA[0] = energyDrinkA[0];
        dpB[0] = energyDrinkB[0];

        for (int i = 1; i < n; i++)
        {
            long switchToA = i >= 2 ? dpB[i - 2] : 0;
            long switchToB = i >= 2 ? dpA[i - 2] : 0;

            dpA[i] = energyDrinkA[i] + Math.Max(dpA[i - 1], switchToA);
            dpB[i] = energyDrinkB[i] + Math.Max(dpB[i - 1], switchToB);
        }

        Console.WriteLine(Math.Max(dpA[n - 1], dpB[n - 1]));
    }

    private static string ReadNonEmptyLine()
    {
        string line;
        while ((line = Console.ReadLine()) != null)
        {
            if (!string.IsNullOrWhiteSpace(line))
                return line;
        }
        return null;
    }

    private static long[] ParseArray(string line)
    {
        var values = new List<long>();
        long number = 0;
        bool readingNumber = false;
        bool negative = false;

        for (int i = 0; i <= line.Length; i++)
        {
            char c = i < line.Length ? line[i] : ' ';

            if (c == '-' && !readingNumber)
            {
                negative = true;
                readingNumber = true;
                number = 0;
            }
            else if (c >= '0' && c <= '9')
            {
                if (!readingNumber)
                {
                    readingNumber = true;
                    negative = false;
                    number = 0;
                }
                number = number * 10 + (c - '0');
            }
            else if (readingNumber)
            {
                values.Add(negative ? -number : number);
                readingNumber = false;
                negative = false;
                number = 0;
            }
        }

        return values.ToArray();
    }
}
