    public static void Main()
    {
        string[] input = Console.In.ReadToEnd()
            .Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        if (input.Length < 2)
            return;

        string word = input[0];
        int k = int.Parse(input[1]);

        long result = CountAtMost(word, k) - CountAtMost(word, k - 1);
        Console.WriteLine(result);
    }

    private static long CountAtMost(string word, int maxConsonants)
    {
        if (maxConsonants < 0)
            return 0;

        int[] lastVowelPositions = { -1, -1, -1, -1, -1 };
        int left = 0;
        int consonants = 0;
        long count = 0;

        for (int right = 0; right < word.Length; right++)
        {
            int vowelIndex = GetVowelIndex(word[right]);

            if (vowelIndex >= 0)
                lastVowelPositions[vowelIndex] = right;
            else
                consonants++;

            while (consonants > maxConsonants)
            {
                if (GetVowelIndex(word[left]) < 0)
                    consonants--;
                left++;
            }

            int earliestLastVowel = lastVowelPositions[0];
            for (int i = 1; i < 5; i++)
                earliestLastVowel = Math.Min(earliestLastVowel, lastVowelPositions[i]);

            if (earliestLastVowel >= left)
                count += earliestLastVowel - left + 1;
        }

        return count;
    }

    private static int GetVowelIndex(char c)
    {
        switch (c)
        {
            case 'a': return 0;
            case 'e': return 1;
            case 'i': return 2;
            case 'o': return 3;
            case 'u': return 4;
            default: return -1;
        }
    }
}
