using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private struct Point
    {
        public int X;
        public int Y;

        public Point(int x, int y)
        {
            X = x;
            Y = y;
        }
    }

    private static int LongestIncreasingChain(List<Point> points)
    {
        points.Sort(delegate(Point a, Point b)
        {
            int cmp = a.X.CompareTo(b.X);
            if (cmp != 0)
                return cmp;

            // Descending Y prevents points with equal X from joining the same chain.
            return b.Y.CompareTo(a.Y);
        });

        int[] tails = new int[points.Count];
        int length = 0;

        foreach (Point point in points)
        {
            int left = 0;
            int right = length;

            // Lower bound: first position whose value is >= point.Y.
            while (left < right)
            {
                int middle = left + (right - left) / 2;
                if (tails[middle] < point.Y)
                    left = middle + 1;
                else
                    right = middle;
            }

            tails[left] = point.Y;
            if (left == length)
                length++;
        }

        return length;
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        Point[] coordinates = new Point[n];

        for (int i = 0; i < n; i++)
            coordinates[i] = new Point(scanner.NextInt(), scanner.NextInt());

        int k = scanner.NextInt();
        Point target = coordinates[k];

        List<Point> lowerLeft = new List<Point>();
        List<Point> upperRight = new List<Point>();

        for (int i = 0; i < n; i++)
        {
            if (i == k)
                continue;

            Point point = coordinates[i];

            if (point.X < target.X && point.Y < target.Y)
                lowerLeft.Add(point);
            else if (point.X > target.X && point.Y > target.Y)
                upperRight.Add(point);
        }

        int answer = LongestIncreasingChain(lowerLeft)
                   + 1
                   + LongestIncreasingChain(upperRight);

        Console.WriteLine(answer);
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;

                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value * sign;
        }
    }
}
