using System;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }

            return buffer[position++];
        }

        public string Next()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c != -1 && c <= 32);

            if (c == -1) return null;

            char[] chars = new char[32];
            int count = 0;

            while (c > 32 && c != -1)
            {
                if (count == chars.Length)
                    Array.Resize(ref chars, chars.Length * 2);

                chars[count++] = (char)c;
                c = ReadByte();
            }

            return new string(chars, 0, count);
        }

        public long NextLong()
        {
            string token = Next();
            return long.Parse(token);
        }
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();

        string s = scanner.Next();
        string t = scanner.Next();

        long[] nextCost = new long[26];
        long[] previousCost = new long[26];

        for (int i = 0; i < 26; i++)
            nextCost[i] = scanner.NextLong();

        for (int i = 0; i < 26; i++)
            previousCost[i] = scanner.NextLong();

        const long INF = long.MaxValue / 4;
        long[,] distance = new long[26, 26];

        for (int i = 0; i < 26; i++)
        {
            for (int j = 0; j < 26; j++)
                distance[i, j] = i == j ? 0 : INF;

            int next = (i + 1) % 26;
            int previous = (i + 25) % 26;

            distance[i, next] = Math.Min(distance[i, next], nextCost[i]);
            distance[i, previous] = Math.Min(distance[i, previous], previousCost[i]);
        }

        for (int k = 0; k < 26; k++)
        {
            for (int i = 0; i < 26; i++)
            {
                for (int j = 0; j < 26; j++)
                {
                    long throughK = distance[i, k] + distance[k, j];
                    if (throughK < distance[i, j])
                        distance[i, j] = throughK;
                }
            }
        }

        long answer = 0;

        for (int i = 0; i < s.Length; i++)
        {
            int from = s[i] - 'a';
            int to = t[i] - 'a';
            answer += distance[from, to];
        }

        Console.WriteLine(answer);
    }
}
