using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;

public class Program
{
    private class Edge
    {
        public string To;
        public double Rate;

        public Edge(string to, double rate)
        {
            To = to;
            Rate = rate;
        }
    }

    private class Scanner
    {
        private readonly string[] tokens;
        private int index;

        public Scanner()
        {
            tokens = Console.In.ReadToEnd()
                .Split((char[])null, StringSplitOptions.RemoveEmptyEntries);
            index = 0;
        }

        public string Next()
        {
            return tokens[index++];
        }

        public int NextInt()
        {
            return int.Parse(Next(), CultureInfo.InvariantCulture);
        }

        public double NextDouble()
        {
            return double.Parse(Next(), CultureInfo.InvariantCulture);
        }
    }

    private static void AddEdge(
        Dictionary<string, List<Edge>> graph,
        string from,
        string to,
        double rate)
    {
        List<Edge> edges;
        if (!graph.TryGetValue(from, out edges))
        {
            edges = new List<Edge>();
            graph[from] = edges;
        }

        edges.Add(new Edge(to, rate));

        if (!graph.ContainsKey(to))
            graph[to] = new List<Edge>();
    }

    private static void AddConversion(
        Dictionary<string, List<Edge>> graph,
        string from,
        string to,
        double rate)
    {
        AddEdge(graph, from, to, rate);
        AddEdge(graph, to, from, 1.0 / rate);
    }

    private static Dictionary<string, double> CalculateRates(
        Dictionary<string, List<Edge>> graph,
        string start)
    {
        var result = new Dictionary<string, double>();
        var stack = new Stack<string>();

        result[start] = 1.0;
        stack.Push(start);

        while (stack.Count > 0)
        {
            string current = stack.Pop();

            List<Edge> edges;
            if (!graph.TryGetValue(current, out edges))
                continue;

            foreach (Edge edge in edges)
            {
                if (!result.ContainsKey(edge.To))
                {
                    result[edge.To] = result[current] * edge.Rate;
                    stack.Push(edge.To);
                }
            }
        }

        return result;
    }

    public static void Main()
    {
        var scanner = new Scanner();

        string initialCurrency = scanner.Next();

        int n = scanner.NextInt();
        string[] from1 = new string[n];
        string[] to1 = new string[n];

        for (int i = 0; i < n; i++)
        {
            from1[i] = scanner.Next();
            to1[i] = scanner.Next();
        }

        var graph1 = new Dictionary<string, List<Edge>>();
        for (int i = 0; i < n; i++)
        {
            double rate = scanner.NextDouble();
            AddConversion(graph1, from1[i], to1[i], rate);
        }

        int m = scanner.NextInt();
        string[] from2 = new string[m];
        string[] to2 = new string[m];

        for (int i = 0; i < m; i++)
        {
            from2[i] = scanner.Next();
            to2[i] = scanner.Next();
        }

        var graph2 = new Dictionary<string, List<Edge>>();
        for (int i = 0; i < m; i++)
        {
            double rate = scanner.NextDouble();
            AddConversion(graph2, from2[i], to2[i], rate);
        }

        Dictionary<string, double> day1Rates =
            CalculateRates(graph1, initialCurrency);
        Dictionary<string, double> day2RatesFromInitial =
            CalculateRates(graph2, initialCurrency);

        double answer = 1.0;

        foreach (KeyValuePair<string, double> entry in day1Rates)
        {
            double initialToCurrencyDay2;
            if (day2RatesFromInitial.TryGetValue(
                entry.Key, out initialToCurrencyDay2))
            {
                double finalAmount = entry.Value / initialToCurrencyDay2;
                if (finalAmount > answer)
                    answer = finalAmount;
            }
        }

        Console.WriteLine(
            answer.ToString("0.0###############", CultureInfo.InvariantCulture));
    }
}
