using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private struct Node
    {
        public long Time;
        public int Position;

        public Node(long time, int position)
        {
            Time = time;
            Position = position;
        }
    }

    private class MinHeap
    {
        private readonly List<Node> heap = new List<Node>();

        public int Count
        {
            get { return heap.Count; }
        }

        public void Push(Node node)
        {
            heap.Add(node);
            int index = heap.Count - 1;

            while (index > 0)
            {
                int parent = (index - 1) / 2;
                if (heap[parent].Time <= heap[index].Time)
                    break;

                Node temp = heap[parent];
                heap[parent] = heap[index];
                heap[index] = temp;
                index = parent;
            }
        }

        public Node Pop()
        {
            Node result = heap[0];
            int lastIndex = heap.Count - 1;
            heap[0] = heap[lastIndex];
            heap.RemoveAt(lastIndex);

            int index = 0;
            while (index < heap.Count)
            {
                int left = index * 2 + 1;
                int right = left + 1;
                int smallest = index;

                if (left < heap.Count && heap[left].Time < heap[smallest].Time)
                    smallest = left;
                if (right < heap.Count && heap[right].Time < heap[smallest].Time)
                    smallest = right;

                if (smallest == index)
                    break;

                Node temp = heap[index];
                heap[index] = heap[smallest];
                heap[smallest] = temp;
                index = smallest;
            }

            return result;
        }
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split(
            (char[])null,
            StringSplitOptions.RemoveEmptyEntries
        );

        if (tokens.Length == 0)
            return;

        int n = int.Parse(tokens[0]);
        int m = (tokens.Length - 1) / n;
        long[,] moveTime = new long[n, m];

        int tokenIndex = 1;
        for (int row = 0; row < n; row++)
        {
            for (int col = 0; col < m; col++)
                moveTime[row, col] = long.Parse(tokens[tokenIndex++]);
        }

        long[,] distance = new long[n, m];
        for (int row = 0; row < n; row++)
        {
            for (int col = 0; col < m; col++)
                distance[row, col] = long.MaxValue;
        }

        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };

        MinHeap heap = new MinHeap();
        distance[0, 0] = 0;
        heap.Push(new Node(0, 0));

        while (heap.Count > 0)
        {
            Node current = heap.Pop();
            int row = current.Position / m;
            int col = current.Position % m;

            if (current.Time != distance[row, col])
                continue;

            if (row == n - 1 && col == m - 1)
            {
                Console.WriteLine(current.Time);
                return;
            }

            for (int direction = 0; direction < 4; direction++)
            {
                int nextRow = row + dr[direction];
                int nextCol = col + dc[direction];

                if (nextRow < 0 || nextRow >= n || nextCol < 0 || nextCol >= m)
                    continue;

                long startTime = Math.Max(current.Time, moveTime[nextRow, nextCol]);
                long arrivalTime = startTime + 1;

                if (arrivalTime < distance[nextRow, nextCol])
                {
                    distance[nextRow, nextCol] = arrivalTime;
                    heap.Push(new Node(arrivalTime, nextRow * m + nextCol));
                }
            }
        }

        Console.WriteLine(distance[n - 1, m - 1]);
    }
}
