using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private struct Query
    {
        public int Left;
        public int Right;

        public Query(int left, int right)
        {
            Left = left;
            Right = right;
        }
    }

    private class MaxHeap
    {
        private readonly int[] heap;
        private int count;

        public MaxHeap(int capacity)
        {
            heap = new int[Math.Max(1, capacity)];
            count = 0;
        }

        public int Count
        {
            get { return count; }
        }

        public void Push(int value)
        {
            int index = count++;
            while (index > 0)
            {
                int parent = (index - 1) / 2;
                if (heap[parent] >= value)
                    break;

                heap[index] = heap[parent];
                index = parent;
            }
            heap[index] = value;
        }

        public int Pop()
        {
            int result = heap[0];
            int value = heap[--count];

            if (count > 0)
            {
                int index = 0;
                while (true)
                {
                    int left = index * 2 + 1;
                    if (left >= count)
                        break;

                    int right = left + 1;
                    int child = left;

                    if (right < count && heap[right] > heap[left])
                        child = right;

                    if (heap[child] <= value)
                        break;

                    heap[index] = heap[child];
                    index = child;
                }
                heap[index] = value;
            }

            return result;
        }
    }

    private static List<int> ParseIntegers(string text)
    {
        var values = new List<int>();
        int i = 0;

        while (i < text.Length)
        {
            while (i < text.Length && !char.IsDigit(text[i]) && text[i] != '-')
                i++;

            if (i >= text.Length)
                break;

            int sign = 1;
            if (text[i] == '-')
            {
                sign = -1;
                i++;
            }

            int value = 0;
            bool hasDigit = false;

            while (i < text.Length && char.IsDigit(text[i]))
            {
                hasDigit = true;
                value = value * 10 + (text[i] - '0');
                i++;
            }

            if (hasDigit)
                values.Add(value * sign);
        }

        return values;
    }

    private static string ReadNonEmptyLine(StreamReader reader)
    {
        string line;
        while ((line = reader.ReadLine()) != null)
        {
            if (!string.IsNullOrWhiteSpace(line))
                return line;
        }
        return null;
    }

    public static void Main()
    {
        var reader = new StreamReader(Console.OpenStandardInput());

        string numsLine = ReadNonEmptyLine(reader);
        if (numsLine == null)
            return;

        List<int> numsValues = ParseIntegers(numsLine);
        int[] nums = numsValues.ToArray();

        string countLine = ReadNonEmptyLine(reader);
        if (countLine == null)
            return;

        List<int> countValues = ParseIntegers(countLine);
        int queryCount = countValues[0];

        List<int> queryValues = ParseIntegers(reader.ReadToEnd());
        Query[] queries = new Query[queryCount];

        for (int i = 0; i < queryCount; i++)
        {
            queries[i] = new Query(queryValues[2 * i], queryValues[2 * i + 1]);
        }

        Array.Sort(queries, delegate(Query a, Query b)
        {
            int comparison = a.Left.CompareTo(b.Left);
            return comparison != 0 ? comparison : b.Right.CompareTo(a.Right);
        });

        int n = nums.Length;
        int[] expirationChanges = new int[n + 1];
        var available = new MaxHeap(queryCount);

        int queryIndex = 0;
        int activeSelected = 0;
        int selectedCount = 0;

        for (int i = 0; i < n; i++)
        {
            activeSelected += expirationChanges[i];

            while (queryIndex < queryCount && queries[queryIndex].Left <= i)
            {
                available.Push(queries[queryIndex].Right);
                queryIndex++;
            }

            while (activeSelected < nums[i])
            {
                if (available.Count == 0)
                {
                    Console.WriteLine(-1);
                    return;
                }

                int right = available.Pop();
                if (right < i)
                {
                    Console.WriteLine(-1);
                    return;
                }

                selectedCount++;
                activeSelected++;

                if (right + 1 < n)
                    expirationChanges[right + 1]--;
            }
        }

        Console.WriteLine(queryCount - selectedCount);
    }
}
