                number = number * 10 + (input[i] - '0');
                i++;
            }

            if (hasDigit)
                values.Add(sign * number);
        }

        int n = values.Count - 1;
        int k = (int)values[values.Count - 1];

        long[] minimumPrefix = new long[k];
        for (int r = 0; r < k; r++)
            minimumPrefix[r] = long.MaxValue;

        minimumPrefix[0] = 0;

        long prefixSum = 0;
        long answer = long.MinValue;

        for (int index = 1; index <= n; index++)
        {
            prefixSum += values[index - 1];
            int remainder = index % k;

            if (minimumPrefix[remainder] != long.MaxValue)
            {
                long candidate = prefixSum - minimumPrefix[remainder];
                if (candidate > answer)
                    answer = candidate;
            }

            if (prefixSum < minimumPrefix[remainder])
                minimumPrefix[remainder] = prefixSum;
        }

        Console.WriteLine(answer);
