public class Program
{
    private const int Mod = 1000000007;

    public static void Main()
    {
        List<string> lines = new List<string>();
        string line;

        while ((line = Console.ReadLine()) != null)
        {
            if (!string.IsNullOrWhiteSpace(line))
                lines.Add(line.Trim());
        }

        if (lines.Count == 0)
            return;

        int m = int.Parse(lines[0]);
        int[][] grid = new int[m][];

        for (int i = 0; i < m; i++)
        {
            string[] parts = lines[i + 1].Split(
                new[] { ' ', '\t' },
                StringSplitOptions.RemoveEmptyEntries);

            grid[i] = new int[parts.Length];
            for (int j = 0; j < parts.Length; j++)
                grid[i][j] = int.Parse(parts[j]);
        }

        int k = int.Parse(lines[m + 1]);
        int n = grid[0].Length;

        int[,] previous = new int[n, 16];
        int[,] current = new int[n, 16];

        for (int i = 0; i < m; i++)
        {
            Array.Clear(current, 0, current.Length);

            for (int j = 0; j < n; j++)
            {
                int value = grid[i][j];

                if (i == 0 && j == 0)
                {
                    current[0, value] = 1;
                    continue;
                }

                for (int xor = 0; xor < 16; xor++)
                {
                    int count = 0;

                    if (i > 0)
                        count = previous[j, xor];

                    if (j > 0)
                    {
                        count += current[j - 1, xor];
                        if (count >= Mod)
                            count -= Mod;
                    }

                    int newXor = xor ^ value;
                    int updated = current[j, newXor] + count;
                    if (updated >= Mod)
                        updated -= Mod;

                    current[j, newXor] = updated;
                }
            }

            int[,] temp = previous;
            previous = current;
            current = temp;
        }

        Console.WriteLine(previous[n - 1, k]);
    }
}
