    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        if (tokens.Length < 2)
            return;

        string word = tokens[0];
        int numFriends = int.Parse(tokens[1]);

        if (numFriends == 1)
        {
            Console.WriteLine(word);
            return;
        }

        int n = word.Length;
        int maxLength = n - numFriends + 1;
        int bestStart = 0;
        int bestLength = Math.Min(maxLength, n);

        for (int start = 1; start < n; start++)
        {
            int length = Math.Min(maxLength, n - start);

            if (IsLexicographicallyGreater(word, start, length, bestStart, bestLength))
            {
                bestStart = start;
                bestLength = length;
            }
        }

        Console.WriteLine(word.Substring(bestStart, bestLength));
    }

    private static bool IsLexicographicallyGreater(
        string word,
        int firstStart,
        int firstLength,
        int secondStart,
        int secondLength)
    {
        int commonLength = Math.Min(firstLength, secondLength);

        for (int i = 0; i < commonLength; i++)
        {
            char first = word[firstStart + i];
            char second = word[secondStart + i];

            if (first != second)
                return first > second;
        }

        return firstLength > secondLength;
    }
}
