        foreach (Match match in matches)
            nums.Add(int.Parse(match.Value));

        int n = nums.Count;
        if (n == 0)
        {
            Console.WriteLine(0);
            return;
        }

        int[] primes = { 2, 3, 5, 7 };
        int[,] exponents = new int[n, primes.Length];

        for (int i = 0; i < n; i++)
        {
            int value = nums[i];
            for (int p = 0; p < primes.Length; p++)
            {
                while (value % primes[p] == 0)
                {
                    exponents[i, p]++;
                    value /= primes[p];
                }
            }
        }

        int longest = 0;

        for (int left = 0; left < n; left++)
        {
            int[] sum = new int[primes.Length];
            int[] min = new int[primes.Length];
            int[] max = new int[primes.Length];

            for (int right = left; right < n; right++)
            {
                for (int p = 0; p < primes.Length; p++)
                {
                    int exponent = exponents[right, p];
                    sum[p] += exponent;

                    if (right == left)
                    {
                        min[p] = exponent;
                        max[p] = exponent;
                    }
                    else
                    {
                        min[p] = Math.Min(min[p], exponent);
                        max[p] = Math.Max(max[p], exponent);
                    }
                }

                bool equivalent = true;
                for (int p = 0; p < primes.Length; p++)
                {
                    if (sum[p] != min[p] + max[p])
                    {
                        equivalent = false;
                        break;
                    }
                }

                if (equivalent)
                    longest = Math.Max(longest, right - left + 1);
            }
        }

        Console.WriteLine(longest);
    }
