using System;
using System.IO;

public class Program
{
    private struct Segment
    {
        public long Left;
        public long Right;
        public long Coins;

        public Segment(long left, long right, long coins)
        {
            Left = left;
            Right = right;
            Coins = coins;
        }
    }

    private static Segment[] segments;
    private static long[] prefix;

    private static long CoinsUpTo(long position)
    {
        int low = 0;
        int high = segments.Length;

        while (low < high)
        {
            int mid = low + (high - low) / 2;
            if (segments[mid].Left <= position)
                low = mid + 1;
            else
                high = mid;
        }

        int index = low - 1;
        if (index < 0)
            return 0;

        long result = prefix[index];
        long coveredRight = Math.Min(position, segments[index].Right);

        if (coveredRight >= segments[index].Left)
        {
            result += (coveredRight - segments[index].Left + 1)
                      * segments[index].Coins;
        }

        return result;
    }

    private static long CoinsInWindow(long left, long right)
    {
        return CoinsUpTo(right) - CoinsUpTo(left - 1);
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        segments = new Segment[n];

        for (int i = 0; i < n; i++)
        {
            long left = scanner.NextLong();
            long right = scanner.NextLong();
            long coins = scanner.NextLong();
            segments[i] = new Segment(left, right, coins);
        }

        long k = scanner.NextLong();

        Array.Sort(segments, delegate (Segment a, Segment b)
        {
            return a.Left.CompareTo(b.Left);
        });

        prefix = new long[n + 1];
        for (int i = 0; i < n; i++)
        {
            long length = segments[i].Right - segments[i].Left + 1;
            prefix[i + 1] = prefix[i] + length * segments[i].Coins;
        }

        long answer = 0;

        for (int i = 0; i < n; i++)
        {
            long startAtLeft = segments[i].Left;
            long value1 = CoinsInWindow(startAtLeft, startAtLeft + k - 1);
            if (value1 > answer)
                answer = value1;

            long endAtRight = segments[i].Right;
            long value2 = CoinsInWindow(endAtRight - k + 1, endAtRight);
            if (value2 > answer)
                answer = value2;
        }

        Console.WriteLine(answer);
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;

                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            long sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value * sign;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }
}
