using System;
using System.Collections.Generic;

public class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<int> nums = ParseIntegers(input);

        if (nums.Count == 0)
        {
            Console.WriteLine(0);
            return;
        }

        const int MaxValue = 300;
        const int MaxDifference = 299;

        int[,] exact = new int[MaxValue + 1, MaxDifference + 1];
        int[,] bestAtLeast = new int[MaxValue + 1, MaxDifference + 1];
        bool[] seen = new bool[MaxValue + 1];
        int[] candidates = new int[MaxDifference + 1];

        int answer = 1;

        foreach (int x in nums)
        {
            Array.Clear(candidates, 0, candidates.Length);

            // Build states ending at the current value using only earlier elements.
            for (int previousValue = 1; previousValue <= MaxValue; previousValue++)
            {
                if (!seen[previousValue])
                    continue;

                int difference = Math.Abs(x - previousValue);
                int length = bestAtLeast[previousValue, difference] + 1;

                if (length > candidates[difference])
                    candidates[difference] = length;
            }

            // Merge the new states into all states ending with value x.
            for (int difference = 0; difference <= MaxDifference; difference++)
            {
                if (candidates[difference] > exact[x, difference])
                    exact[x, difference] = candidates[difference];

                if (candidates[difference] > answer)
                    answer = candidates[difference];
            }

            seen[x] = true;

            // bestAtLeast[x, d] is the best state whose last difference is >= d.
            // A one-element subsequence can be followed by any possible difference.
            int runningBest = 1;
            for (int difference = MaxDifference; difference >= 0; difference--)
            {
                if (exact[x, difference] > runningBest)
                    runningBest = exact[x, difference];

                bestAtLeast[x, difference] = runningBest;
            }
        }

        Console.WriteLine(answer);
    }

    private static List<int> ParseIntegers(string text)
    {
        List<int> result = new List<int>();

        for (int i = 0; i < text.Length;)
        {
            while (i < text.Length && !char.IsDigit(text[i]) && text[i] != '-')
                i++;

            if (i >= text.Length)
                break;

            int sign = 1;
            if (text[i] == '-')
            {
                sign = -1;
                i++;
            }

            if (i >= text.Length || !char.IsDigit(text[i]))
                continue;

            int value = 0;
            while (i < text.Length && char.IsDigit(text[i]))
            {
                value = value * 10 + (text[i] - '0');
                i++;
            }

            result.Add(value * sign);
        }

        return result;
    }
}
