using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value * sign;
        }
    }

    private static int LowerBound(int[] array, int value)
    {
        int left = 0;
        int right = array.Length;

        while (left < right)
        {
            int middle = left + (right - left) / 2;
            if (array[middle] < value)
                left = middle + 1;
            else
                right = middle;
        }

        return left;
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();

        scanner.NextInt(); // W
        scanner.NextInt(); // H

        int n = scanner.NextInt();
        int[] p = new int[n];
        int[] q = new int[n];

        for (int i = 0; i < n; i++)
        {
            p[i] = scanner.NextInt();
            q[i] = scanner.NextInt();
        }

        int aCount = scanner.NextInt();
        int[] verticalCuts = new int[aCount];
        for (int i = 0; i < aCount; i++)
            verticalCuts[i] = scanner.NextInt();

        int bCount = scanner.NextInt();
        int[] horizontalCuts = new int[bCount];
        for (int i = 0; i < bCount; i++)
            horizontalCuts[i] = scanner.NextInt();

        long columnCount = aCount + 1L;
        long rowCount = bCount + 1L;
        long totalPieces = columnCount * rowCount;

        Dictionary<long, int> counts = new Dictionary<long, int>(n);
        int maximum = 0;

        for (int i = 0; i < n; i++)
        {
            int column = LowerBound(verticalCuts, p[i]);
            int row = LowerBound(horizontalCuts, q[i]);
            long key = column * rowCount + row;

            int current;
            if (counts.TryGetValue(key, out current))
                current++;
            else
                current = 1;

            counts[key] = current;
            if (current > maximum)
                maximum = current;
        }

        int minimum;
        if ((long)counts.Count < totalPieces)
        {
            minimum = 0;
        }
        else
        {
            minimum = int.MaxValue;
            foreach (int count in counts.Values)
            {
                if (count < minimum)
                    minimum = count;
            }
        }

        Console.WriteLine(minimum + " " + maximum);
    }
}
