    private sealed class MaxHeap
    {
        private readonly int[] data;
        private int count;

        public MaxHeap(int capacity)
        {
            data = new int[capacity];
        }

        public int Count
        {
            get { return count; }
        }

        public void Push(int value)
        {
            int index = count++;
            while (index > 0)
            {
                int parent = (index - 1) / 2;
                if (data[parent] >= value)
                    break;

                data[index] = data[parent];
                index = parent;
            }
            data[index] = value;
        }

        public int Pop()
        {
            int result = data[0];
            int value = data[--count];

            if (count > 0)
            {
                int index = 0;
                while (true)
                {
                    int left = index * 2 + 1;
                    if (left >= count)
                        break;

                    int right = left + 1;
                    int larger = left;

                    if (right < count && data[right] > data[left])
                        larger = right;

                    if (data[larger] <= value)
                        break;

                    data[index] = data[larger];
                    index = larger;
                }
                data[index] = value;
            }

            return result;
        }
    }

    public static void Main()
    {
        var reader = new FastScanner(Console.OpenStandardInput());

        int n = reader.NextInt();
        int m = reader.NextInt();

        int[] prices = new int[n];
        long answer = 0;

        for (int i = 0; i < n; i++)
        {
            prices[i] = reader.NextInt();
            answer += prices[i];
        }

        int[] limits = new int[m];
        for (int i = 0; i < m; i++)
            limits[i] = reader.NextInt();

        Coupon[] coupons = new Coupon[m];
        for (int i = 0; i < m; i++)
        {
            coupons[i].Limit = limits[i];
            coupons[i].Discount = reader.NextInt();
        }

        Array.Sort(prices);
        Array.Sort(coupons);

        var heap = new MaxHeap(m);
        int couponIndex = 0;

        for (int i = 0; i < n; i++)
        {
            while (couponIndex < m && coupons[couponIndex].Limit <= prices[i])
            {
                heap.Push(coupons[couponIndex].Discount);
                couponIndex++;
            }

            if (heap.Count > 0)
                answer -= heap.Pop();
        }

        Console.WriteLine(answer);
    }

