using System;
using System.Globalization;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value * sign;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        int[] x = new int[n];
        int[] y = new int[n];

        for (int i = 0; i < n; i++)
        {
            x[i] = scanner.NextInt();
            y[i] = scanner.NextInt();
        }

        const int MaxSkipped = 30;
        double[,] dp = new double[n, MaxSkipped + 1];

        for (int i = 0; i < n; i++)
        {
            for (int skipped = 0; skipped <= MaxSkipped; skipped++)
            {
                dp[i, skipped] = double.PositiveInfinity;
            }
        }

        dp[0, 0] = 0.0;

        for (int i = 1; i < n; i++)
        {
            int firstPrevious = Math.Max(0, i - MaxSkipped - 1);

            for (int previous = firstPrevious; previous < i; previous++)
            {
                int newlySkipped = i - previous - 1;
                double dx = x[i] - x[previous];
                double dy = y[i] - y[previous];
                double distance = Math.Sqrt(dx * dx + dy * dy);

                for (int skipped = 0;
                     skipped + newlySkipped <= MaxSkipped;
                     skipped++)
                {
                    if (double.IsPositiveInfinity(dp[previous, skipped]))
                        continue;

                    int totalSkipped = skipped + newlySkipped;
                    double candidate = dp[previous, skipped] + distance;

                    if (candidate < dp[i, totalSkipped])
                    {
                        dp[i, totalSkipped] = candidate;
                    }
                }
            }
        }

        double answer = double.PositiveInfinity;

        for (int skipped = 0; skipped <= MaxSkipped; skipped++)
        {
            double penalty = skipped == 0 ? 0.0 : Math.Pow(2.0, skipped - 1);
            answer = Math.Min(answer, dp[n - 1, skipped] + penalty);
        }

        Console.WriteLine(answer.ToString("R", CultureInfo.InvariantCulture));
    }
}
