            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int m = (n % 2 == 0) ? n : n + 1;

        long[,] weight = new long[m, m];

        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                weight[i, j] = weight[j, i] = scanner.NextInt();
            }
        }

        int fullMask = (1 << m) - 1;
        long[] dp = new long[1 << m];

        for (int mask = 1; mask <= fullMask; mask++)
            dp[mask] = long.MinValue;

        for (int mask = 0; mask < fullMask; mask++)
        {
            if (dp[mask] == long.MinValue) continue;

            int first = 0;
            while ((mask & (1 << first)) != 0)
                first++;

            int maskWithFirst = mask | (1 << first);

            for (int second = first + 1; second < m; second++)
            {
                if ((mask & (1 << second)) != 0) continue;

                int nextMask = maskWithFirst | (1 << second);
                long candidate = dp[mask] + weight[first, second];

                if (candidate > dp[nextMask])
                    dp[nextMask] = candidate;
            }
        }

        Console.WriteLine(dp[fullMask]);
    }
}
