using System;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        int[] head = new int[n];
        Array.Fill(head, -1);

        int[] to = new int[2 * (n - 1)];
        int[] next = new int[2 * (n - 1)];
        int edgeIndex = 0;

        for (int i = 0; i < n - 1; i++)
        {
            int u = scanner.NextInt() - 1;
            int v = scanner.NextInt() - 1;

            to[edgeIndex] = v;
            next[edgeIndex] = head[u];
            head[u] = edgeIndex++;

            to[edgeIndex] = u;
            next[edgeIndex] = head[v];
            head[v] = edgeIndex++;
        }

        int[] parent = new int[n];
        int[] order = new int[n];
        int[] stack = new int[n];

        parent[0] = -1;
        int stackSize = 0;
        int orderSize = 0;
        stack[stackSize++] = 0;

        while (stackSize > 0)
        {
            int vertex = stack[--stackSize];
            order[orderSize++] = vertex;

            for (int e = head[vertex]; e != -1; e = next[e])
            {
                int neighbor = to[e];
                if (neighbor == parent[vertex]) continue;

                parent[neighbor] = vertex;
                stack[stackSize++] = neighbor;
            }
        }

        int[] subtreeSize = new int[n];
        Array.Fill(subtreeSize, 1);
        int largestComponent = 0;

        for (int i = orderSize - 1; i > 0; i--)
        {
            int vertex = order[i];
            int p = parent[vertex];

            if (p == 0 && subtreeSize[vertex] > largestComponent)
                largestComponent = subtreeSize[vertex];

            subtreeSize[p] += subtreeSize[vertex];
        }

        Console.WriteLine(n - largestComponent);
    }
}
