    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int index;

        private int Read()
        {
            if (index >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                index = 0;
                if (length == 0) return -1;
            }
            return buffer[index++];
        }

        public string Next()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            var sb = new StringBuilder();
            while (c > 32 && c != -1)
            {
                sb.Append((char)c);
                c = Read();
            }
            return sb.ToString();
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value * sign;
        }

        public char NextChar()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);
            return (char)c;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int q = scanner.NextInt();

        int[] headX = new int[q + 1];
        int[] headY = new int[q + 1];
        headX[0] = 1;
        headY[0] = 0;

        int moves = 0;
        var output = new StringBuilder();

        for (int i = 0; i < q; i++)
        {
            int type = scanner.NextInt();

            if (type == 1)
            {
                char direction = scanner.NextChar();
                moves++;

                headX[moves] = headX[moves - 1];
                headY[moves] = headY[moves - 1];

                switch (direction)
                {
                    case 'R':
                        headX[moves]++;
                        break;
                    case 'L':
                        headX[moves]--;
                        break;
                    case 'U':
                        headY[moves]++;
                        break;
                    case 'D':
                        headY[moves]--;
                        break;
                }
            }
            else
            {
                int p = scanner.NextInt();

                if (p - 1 <= moves)
                {
                    int historyIndex = moves - (p - 1);
                    output.Append(headX[historyIndex])
                          .Append(' ')
                          .Append(headY[historyIndex])
                          .Append('\n');
                }
                else
                {
                    output.Append(p - moves)
                          .Append(" 0\n");
                }
            }
        }

        Console.Write(output.ToString());
    }
}
