using System;
using System.IO;

class Program
{
    const int INF = 1000000000;

    static void Main()
    {
        FastScanner fs = new FastScanner();

        int n = fs.NextInt();
        int m = fs.NextInt();

        int[] dist = new int[n * n];
        for (int i = 0; i < dist.Length; i++)
            dist[i] = INF;

        for (int i = 0; i < n; i++)
            dist[i * n + i] = 0;

        for (int i = 0; i < m; i++)
        {
            int u = fs.NextInt() - 1;
            int v = fs.NextInt() - 1;
            int w = fs.NextInt();
            dist[u * n + v] = w;
        }

        // All-pairs shortest paths.
        for (int k = 0; k < n; k++)
        {
            int kBase = k * n;
            for (int i = 0; i < n; i++)
            {
                int iBase = i * n;
                int dik = dist[iBase + k];
                if (dik == INF)
                    continue;

                for (int j = 0; j < n; j++)
                {
                    int dkj = dist[kBase + j];
                    if (dkj == INF)
                        continue;

                    int candidate = dik + dkj;
                    if (candidate < dist[iBase + j])
                        dist[iBase + j] = candidate;
                }
            }
        }

        // Any two vertices visited by one walk must be reachable in at least
        // one direction.
        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                if (dist[i * n + j] == INF && dist[j * n + i] == INF)
                {
                    Console.WriteLine("No");
                    return;
                }
            }
        }

        int size = 1 << n;
        byte[] bitIndex = new byte[size];
        for (int i = 0; i < n; i++)
            bitIndex[1 << i] = (byte)i;

        // costTo[v, u] = shortest distance from u to v.
        int[] costTo = new int[n * n];
        for (int v = 0; v < n; v++)
        {
            int vBase = v * n;
            for (int u = 0; u < n; u++)
                costTo[vBase + u] = dist[u * n + v];
        }

        // dp[mask, v]: minimum cost of a shortest-path Hamiltonian path
        // over the metric closure, visiting mask and ending at v.
        int[] dp = new int[size * n];

        for (int mask = 1; mask < size; mask++)
        {
            int maskBase = mask * n;
            int vertices = mask;

            while (vertices != 0)
            {
                int vBit = vertices & -vertices;
                int v = bitIndex[vBit];
                int previousMask = mask ^ vBit;

                if (previousMask == 0)
                {
                    dp[maskBase + v] = 0;
                }
                else
                {
                    int best = INF;
                    int previousBase = previousMask * n;
                    int costBase = v * n;
                    int ends = previousMask;

                    while (ends != 0)
                    {
                        int uBit = ends & -ends;
                        int u = bitIndex[uBit];

                        int previousCost = dp[previousBase + u];
                        int edgeCost = costTo[costBase + u];

                        if (previousCost != INF && edgeCost != INF)
                        {
                            int candidate = previousCost + edgeCost;
                            if (candidate < best)
                                best = candidate;
                        }

                        ends -= uBit;
                    }

                    dp[maskBase + v] = best;
                }

                vertices -= vBit;
            }
        }

        int allBase = (size - 1) * n;
        int answer = INF;

        for (int v = 0; v < n; v++)
        {
            if (dp[allBase + v] < answer)
                answer = dp[allBase + v];
        }

        if (answer == INF)
            Console.WriteLine("No");
        else
            Console.WriteLine(answer);
    }

    sealed class FastScanner
    {
        readonly Stream input = Console.OpenStandardInput();
        readonly byte[] buffer = new byte[1 << 16];
        int length;
        int position;

        int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

