            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int t = scanner.NextInt();

        var scores = new long[n];
        var frequencies = new Dictionary<long, int>();
        frequencies[0] = n;

        var output = new StringBuilder();

        for (int i = 0; i < t; i++)
        {
            int player = scanner.NextInt() - 1;
            long increase = scanner.NextLong();

            long oldScore = scores[player];
            int oldCount = frequencies[oldScore];

            if (oldCount == 1)
                frequencies.Remove(oldScore);
            else
                frequencies[oldScore] = oldCount - 1;

            long newScore = oldScore + increase;
            scores[player] = newScore;

            int newCount;
            if (frequencies.TryGetValue(newScore, out newCount))
                frequencies[newScore] = newCount + 1;
            else
                frequencies[newScore] = 1;

