    private sealed class FastScanner
    {
        private readonly TextReader reader;
        private string[] tokens = new string[0];
        private int index;

        public FastScanner(TextReader reader)
        {
            this.reader = reader;
        }

        public string Next()
        {
            while (index >= tokens.Length)
            {
                string line = reader.ReadLine();
                if (line == null) return null;
                tokens = line.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);
                index = 0;
            }

            return tokens[index++];
        }

        public int NextInt()
        {
            return int.Parse(Next());
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner(Console.In);
        string target = scanner.Next();
        int n = scanner.NextInt();
        int length = target.Length;
        const int INF = 1000000000;

        int[] dp = new int[length + 1];
        for (int i = 1; i <= length; i++)
            dp[i] = INF;

        for (int bag = 0; bag < n; bag++)
        {
            int count = scanner.NextInt();
            string[] words = new string[count];

            for (int i = 0; i < count; i++)
                words[i] = scanner.Next();

            int[] next = (int[])dp.Clone();

            for (int position = 0; position <= length; position++)
            {
                if (dp[position] == INF)
                    continue;

                foreach (string word in words)
                {
                    if (Matches(target, position, word))
                    {
                        int newPosition = position + word.Length;
                        next[newPosition] = Math.Min(next[newPosition], dp[position] + 1);
                    }
                }
            }

            dp = next;
        }

        Console.WriteLine(dp[length] == INF ? -1 : dp[length]);
    }

    private static bool Matches(string target, int position, string word)
    {
        if (position + word.Length > target.Length)
            return false;

        for (int i = 0; i < word.Length; i++)
        {
            if (target[position + i] != word[i])
                return false;
        }

        return true;
    }
}
