using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

public class Program
{
    private class Node
    {
        public long Value;
        public Node Prev;
        public Node Next;

        public Node(long value)
        {
            Value = value;
        }
    }

    private class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            long sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value * sign;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        var nodes = new Dictionary<long, Node>(n * 2);
        Node head = null;
        Node tail = null;

        for (int i = 0; i < n; i++)
        {
            long value = scanner.NextLong();
            var node = new Node(value);

            if (head == null)
            {
                head = tail = node;
            }
            else
            {
                tail.Next = node;
                node.Prev = tail;
                tail = node;
            }

            nodes[value] = node;
        }

        int q = scanner.NextInt();

        for (int i = 0; i < q; i++)
        {
            int type = scanner.NextInt();
            long x = scanner.NextLong();

            if (type == 1)
            {
                long y = scanner.NextLong();
                Node current = nodes[x];
                Node next = current.Next;
                Node inserted = new Node(y);

                inserted.Prev = current;
                inserted.Next = next;
                current.Next = inserted;

                if (next != null)
                    next.Prev = inserted;
                else
                    tail = inserted;

                nodes[y] = inserted;
            }
            else
            {
                Node current = nodes[x];
                Node prev = current.Prev;
                Node next = current.Next;

                if (prev != null)
                    prev.Next = next;
                else
                    head = next;

                if (next != null)
                    next.Prev = prev;
                else
                    tail = prev;

                nodes.Remove(x);
            }
        }

        var output = new StringBuilder();
        Node cursor = head;
        while (cursor != null)
        {
            if (output.Length > 0)
                output.Append(' ');

            output.Append(cursor.Value);
            cursor = cursor.Next;
        }

        Console.WriteLine(output.ToString());
    }
}
