    private static readonly long[,] Pattern =
    {
        { 2, 1, 0, 1 },
        { 1, 2, 1, 0 }
    };

    private static long Prefix(long x, long y)
    {
        long result = 0;

        for (int row = 0; row < 2; row++)
        {
            long countY = y / 2 + (row < y % 2 ? 1 : 0);

            for (int column = 0; column < 4; column++)
            {
                long countX = x / 4 + (column < x % 4 ? 1 : 0);
                result += countX * countY * Pattern[row, column];
            }
        }

        return result;
    }

    public static void Main()
    {
        string[] input = Console.In.ReadToEnd()
            .Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

