using System;

public class Program
{
    const long Mod = 998244353;

    static long ModPow(long value, int exponent)
    {
        long result = 1;
        value %= Mod;

        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * value % Mod;

            value = value * value % Mod;
            exponent >>= 1;
        }

        return result;
    }

    public static void Main()
    {
        string input = Console.ReadLine().Trim();
        long n = long.Parse(input);
        int digits = input.Length;

        long block = n % Mod;
        long baseValue = ModPow(10, digits);

        // Computes 1 + baseValue + ... + baseValue^(n - 1).
        long resultPower = 1;
        long resultSum = 0;
        long currentPower = baseValue;
        long currentSum = 1;
        long count = n;

        while (count > 0)
        {
            if ((count & 1) != 0)
            {
                resultSum = (resultSum + resultPower * currentSum) % Mod;
                resultPower = resultPower * currentPower % Mod;
            }

            currentSum = currentSum * (1 + currentPower) % Mod;
            currentPower = currentPower * currentPower % Mod;
            count >>= 1;
        }

        long answer = block * resultSum % Mod;
        Console.WriteLine(answer);
    }
}
