public class Program
{
    const int Mod = 998244353;

    public static void Main()
    {
        FastScanner fs = new FastScanner(Console.OpenStandardInput());

        int k = fs.NextInt();
        int[] limits = new int[26];
        for (int i = 0; i < 26; i++)
            limits[i] = fs.NextInt();

        int[] fact = new int[k + 1];
        int[] invFact = new int[k + 1];

        fact[0] = 1;
        for (int i = 1; i <= k; i++)
            fact[i] = (int)((long)fact[i - 1] * i % Mod);

        invFact[k] = ModPow(fact[k], Mod - 2);
        for (int i = k; i >= 1; i--)
            invFact[i - 1] = (int)((long)invFact[i] * i % Mod);

        int[] dp = new int[k + 1];
        int[] next = new int[k + 1];
        dp[0] = 1;

        int currentMax = 0;

        for (int letter = 0; letter < 26; letter++)
        {
            Array.Clear(next, 0, next.Length);
            int limit = Math.Min(limits[letter], k);
            int nextMax = Math.Min(k, currentMax + limit);

            for (int used = 0; used <= currentMax; used++)
            {
                if (dp[used] == 0)
                    continue;

                int maxAdd = Math.Min(limit, k - used);
                for (int add = 0; add <= maxAdd; add++)
                {
                    int index = used + add;
                    int value = (int)((long)dp[used] * invFact[add] % Mod);
                    int sum = next[index] + value;
                    if (sum >= Mod)
                        sum -= Mod;
                    next[index] = sum;
                }
            }

            int[] temp = dp;
            dp = next;
            next = temp;
            currentMax = nextMax;
        }

        int answer = 0;
        for (int length = 1; length <= k; length++)
        {
            int value = (int)((long)dp[length] * fact[length] % Mod);
            answer += value;
            if (answer >= Mod)
                answer -= Mod;
        }

        Console.WriteLine(answer);
    }

    static int ModPow(int value, int exponent)
    {
        long result = 1;
        long current = value;

        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * current % Mod;

            current = current * current % Mod;
            exponent >>= 1;
        }

        return (int)result;
    }

    sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c >= 0);

            int value = 0;
            while (c > 32)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }
    }
