using System;
using System.IO;

public class Program
{
    private static int[] head;
    private static int[] to;
    private static int[] next;
    private static long[] weight;
    private static int edgeCount;
    private static int n;

    private static void AddEdge(int from, int dest, long cost)
    {
        to[edgeCount] = dest;
        weight[edgeCount] = cost;
        next[edgeCount] = head[from];
        head[from] = edgeCount++;
    }

    private static Tuple<int, long> FindFarthest(int start)
    {
        int[] stackNode = new int[n];
        int[] stackParent = new int[n];
        long[] stackDistance = new long[n];
        int stackSize = 0;

        stackNode[stackSize] = start;
        stackParent[stackSize] = -1;
        stackDistance[stackSize] = 0;
        stackSize++;

        int farthestNode = start;
        long farthestDistance = 0;

        while (stackSize > 0)
        {
            stackSize--;
            int node = stackNode[stackSize];
            int parent = stackParent[stackSize];
            long distance = stackDistance[stackSize];

            if (distance > farthestDistance)
            {
                farthestDistance = distance;
                farthestNode = node;
            }

            for (int e = head[node]; e != -1; e = next[e])
            {
                int neighbor = to[e];
                if (neighbor == parent)
                    continue;

                stackNode[stackSize] = neighbor;
                stackParent[stackSize] = node;
                stackDistance[stackSize] = distance + weight[e];
                stackSize++;
            }
        }

        return Tuple.Create(farthestNode, farthestDistance);
    }

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());

        n = scanner.NextInt();
        head = new int[n];
        Array.Fill(head, -1);

        int directedEdges = 2 * (n - 1);
        to = new int[directedEdges];
        next = new int[directedEdges];
        weight = new long[directedEdges];

        long totalLength = 0;

        for (int i = 0; i < n - 1; i++)
        {
            int a = scanner.NextInt() - 1;
            int b = scanner.NextInt() - 1;
            long c = scanner.NextLong();

            AddEdge(a, b, c);
            AddEdge(b, a, c);
            totalLength += c;
        }

        int diameterEndpoint = FindFarthest(0).Item1;
        long diameter = FindFarthest(diameterEndpoint).Item2;

        long answer = 2L * totalLength - diameter;
        Console.WriteLine(answer);
    }

