            {
                long difference = a[i] - a[j];

                int[] current;
                if (!dp[i].TryGetValue(difference, out current))
                {
                    current = new int[n + 1];
                    dp[i][difference] = current;
                }

                current[2]++;
                if (current[2] >= Mod)
                    current[2] -= Mod;

                answer[2]++;
                if (answer[2] >= Mod)
                    answer[2] -= Mod;

                int[] previous;
                if (!dp[j].TryGetValue(difference, out previous))
                    continue;

                for (int length = 2; length < n; length++)
                {
                    if (previous[length] == 0)
                        continue;

                    int nextLength = length + 1;

                    current[nextLength] += previous[length];
                    if (current[nextLength] >= Mod)
                        current[nextLength] -= Mod;

                    answer[nextLength] += previous[length];
                    if (answer[nextLength] >= Mod)
                        answer[nextLength] -= Mod;
                }
            }
        }

