using System;
using System.IO;
using System.Text;

public class Program
{
    private struct Query
    {
        public int L;
        public int R;
        public int C;
    }

    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    private static int[] parent;

    private static int Find(int x)
    {
        int root = x;
        while (parent[root] != root)
            root = parent[root];

        while (parent[x] != x)
        {
            int next = parent[x];
            parent[x] = root;
            x = next;
        }

        return root;
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int q = scanner.NextInt();

        var queries = new Query[q];
        long answer = 0;

        for (int i = 0; i < q; i++)
        {
            int l = scanner.NextInt();
            int r = scanner.NextInt();
            int c = scanner.NextInt();

            queries[i] = new Query { L = l, R = r, C = c };
            answer += c;
        }

        Array.Sort(queries, delegate (Query a, Query b)
        {
            return a.C.CompareTo(b.C);
        });

        // Positions 1 through N-1 represent boundaries between adjacent vertices.
        // N is a sentinel meaning that no unprocessed boundary remains.
        parent = new int[n + 1];
        for (int i = 0; i <= n; i++)
            parent[i] = i;

        int connectedBoundaries = 0;

        for (int i = 0; i < q; i++)
        {
            Query query = queries[i];
            int boundary = Find(query.L);

            while (boundary < query.R)
            {
                answer += query.C;
                connectedBoundaries++;

                int next = Find(boundary + 1);
                parent[boundary] = next;
                boundary = next;
            }
        }

        if (connectedBoundaries != n - 1)
            Console.WriteLine("-1");
        else
            Console.WriteLine(answer);
    }
}
