            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value * sign;
        }
    }

    private static int[] BuildCostCounts(int[] coordinates, int d)
    {
        Array.Sort(coordinates);

        int n = coordinates.Length;
        int left = coordinates[n - 1] - d;
        int right = coordinates[0] + d;
        int[] counts = new int[d + 1];

        if (left > right)
            return counts;

        long cost = 0;
        for (int i = 0; i < n; i++)
            cost += Math.Abs((long)left - coordinates[i]);

        int lessOrEqual = 0;
        while (lessOrEqual < n && coordinates[lessOrEqual] <= left)
            lessOrEqual++;

        for (int position = left; position <= right; position++)
        {
            if (cost <= d)
                counts[(int)cost]++;

            if (position == right)
                break;

            cost += 2L * lessOrEqual - n;

            int nextPosition = position + 1;
            while (lessOrEqual < n &&
                   coordinates[lessOrEqual] <= nextPosition)
            {
                lessOrEqual++;
            }
        }

        return counts;
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int d = scanner.NextInt();

        int[] xs = new int[n];
        int[] ys = new int[n];

        for (int i = 0; i < n; i++)
        {
            xs[i] = scanner.NextInt();
            ys[i] = scanner.NextInt();
        }

        int[] xCounts = BuildCostCounts(xs, d);
        int[] yCounts = BuildCostCounts(ys, d);

        long[] yPrefix = new long[d + 1];
        long running = 0;

        for (int cost = 0; cost <= d; cost++)
        {
            running += yCounts[cost];
            yPrefix[cost] = running;
        }

        long answer = 0;
        for (int xCost = 0; xCost <= d; xCost++)
        {
            answer += (long)xCounts[xCost] * yPrefix[d - xCost];
        }

        Console.WriteLine(answer);
    }
}
