using System;
using System.IO;
using System.Text;

public class Program
{
    private const long INF = long.MaxValue / 4;

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        int m = scanner.NextInt();

        int[] u = new int[m];
        int[] v = new int[m];
        long[] t = new long[m];

        long[][] dist = new long[n][];
        for (int i = 0; i < n; i++)
        {
            dist[i] = new long[n];
            for (int j = 0; j < n; j++)
                dist[i][j] = (i == j) ? 0 : INF;
        }

        for (int i = 0; i < m; i++)
        {
            u[i] = scanner.NextInt() - 1;
            v[i] = scanner.NextInt() - 1;
            t[i] = scanner.NextLong();

            if (t[i] < dist[u[i]][v[i]])
            {
                dist[u[i]][v[i]] = t[i];
                dist[v[i]][u[i]] = t[i];
            }
        }

        for (int k = 0; k < n; k++)
        {
            long[] dk = dist[k];
            for (int i = 0; i < n; i++)
            {
                long[] di = dist[i];
                long dik = di[k];
                if (dik == INF) continue;

                for (int j = 0; j < n; j++)
                {
                    long candidate = dik + dk[j];
                    if (candidate < di[j])
                        di[j] = candidate;
                }
            }
        }

        int q = scanner.NextInt();
        StringBuilder output = new StringBuilder();

        for (int query = 0; query < q; query++)
        {
            int k = scanner.NextInt();
            int[] bridges = new int[k];

            for (int i = 0; i < k; i++)
                bridges[i] = scanner.NextInt() - 1;

            int maskCount = 1 << k;
            long[] dp = new long[maskCount * k * 2];

            for (int i = 0; i < dp.Length; i++)
                dp[i] = INF;

            for (int i = 0; i < k; i++)
            {
                int edge = bridges[i];

                // Orientation 0: u -> v
                dp[((1 << i) * k + i) * 2] =
                    dist[0][u[edge]] + t[edge];

                // Orientation 1: v -> u
                dp[((1 << i) * k + i) * 2 + 1] =
                    dist[0][v[edge]] + t[edge];
            }

            for (int mask = 1; mask < maskCount; mask++)
            {
                for (int last = 0; last < k; last++)
                {
                    if ((mask & (1 << last)) == 0) continue;

                    int lastEdge = bridges[last];

                    for (int orientation = 0; orientation < 2; orientation++)
                    {
                        long current = dp[(mask * k + last) * 2 + orientation];
                        if (current == INF) continue;

                        int currentIsland = orientation == 0
                            ? v[lastEdge]
                            : u[lastEdge];

                        for (int next = 0; next < k; next++)
                        {
                            if ((mask & (1 << next)) != 0) continue;

                            int nextEdge = bridges[next];
                            int nextMask = mask | (1 << next);

                            long candidate0 = current
                                + dist[currentIsland][u[nextEdge]]
                                + t[nextEdge];
                            int index0 = (nextMask * k + next) * 2;
                            if (candidate0 < dp[index0])
                                dp[index0] = candidate0;

                            long candidate1 = current
                                + dist[currentIsland][v[nextEdge]]
                                + t[nextEdge];
                            int index1 = index0 + 1;
                            if (candidate1 < dp[index1])
                                dp[index1] = candidate1;
                        }
                    }
                }
            }

            int fullMask = maskCount - 1;
            long answer = INF;

            for (int last = 0; last < k; last++)
            {
                int edge = bridges[last];

                long candidate0 =
                    dp[(fullMask * k + last) * 2] + dist[v[edge]][n - 1];
                if (candidate0 < answer)
                    answer = candidate0;

                long candidate1 =
                    dp[(fullMask * k + last) * 2 + 1] + dist[u[edge]][n - 1];
                if (candidate1 < answer)
                    answer = candidate1;
            }

            output.AppendLine(answer.ToString());
        }

        Console.Write(output.ToString());
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

