                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            long sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value * sign;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    private static int LowerBound(long[] values, long target)
    {
        int left = 0;
        int right = values.Length;

        while (left < right)
        {
            int middle = left + (right - left) / 2;
            if (values[middle] < target)
                left = middle + 1;
            else
                right = middle;
        }

        return left;
    }

    private static int UpperBound(long[] values, long target)
    {
        int left = 0;
        int right = values.Length;

        while (left < right)
        {
            int middle = left + (right - left) / 2;
            if (values[middle] <= target)
                left = middle + 1;
            else
                right = middle;
        }

        return left;
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        var coordinates = new long[n];
        for (int i = 0; i < n; i++)
            coordinates[i] = scanner.NextLong();

        var prefixSum = new long[n + 1];
        for (int i = 0; i < n; i++)
            prefixSum[i + 1] = prefixSum[i] + scanner.NextLong();

        int q = scanner.NextInt();
        var output = new StringBuilder();

        for (int i = 0; i < q; i++)
        {
            long l = scanner.NextLong();
            long r = scanner.NextLong();

            int leftIndex = LowerBound(coordinates, l);
            int rightIndex = UpperBound(coordinates, r);

            long answer = prefixSum[rightIndex] - prefixSum[leftIndex];
            output.AppendLine(answer.ToString());
        }

        Console.Write(output.ToString());
    }
