using System.Text;

public class Program
{
    private static int[] parent;
    private static int[] top;
    private static int[] count;
    private static readonly int[] merged = new int[10];

    private static int Find(int x)
    {
        int root = x;
        while (parent[root] >= 0)
            root = parent[root];

        while (x != root)
        {
            int next = parent[x];
            parent[x] = root;
            x = next;
        }

        return root;
    }

    private static void Union(int a, int b)
    {
        int ra = Find(a);
        int rb = Find(b);

        if (ra == rb)
            return;

        int ia = 0;
        int ib = 0;
        int total = 0;

        while (total < 10 && (ia < count[ra] || ib < count[rb]))
        {
            if (ib >= count[rb] ||
                (ia < count[ra] && top[ra * 10 + ia] > top[rb * 10 + ib]))
            {
                merged[total++] = top[ra * 10 + ia++];
            }
            else
            {
                merged[total++] = top[rb * 10 + ib++];
            }
        }

        if (parent[ra] > parent[rb])
        {
            int temp = ra;
            ra = rb;
            rb = temp;
        }

        parent[ra] += parent[rb];
        parent[rb] = ra;
        count[ra] = total;

        int offset = ra * 10;
        for (int i = 0; i < total; i++)
            top[offset + i] = merged[i];
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        int q = scanner.NextInt();

        parent = new int[n];
        top = new int[n * 10];
        count = new int[n];

        for (int i = 0; i < n; i++)
        {
            parent[i] = -1;
            count[i] = 1;
            top[i * 10] = i + 1;
        }

        StringBuilder output = new StringBuilder();

        for (int i = 0; i < q; i++)
        {
            int type = scanner.NextInt();
            int x = scanner.NextInt() - 1;
            int y = scanner.NextInt();

            if (type == 1)
            {
                Union(x, y - 1);
            }
            else
            {
                int root = Find(x);
                int k = y;

                if (count[root] < k)
                    output.AppendLine("-1");
                else
                    output.AppendLine(top[root * 10 + k - 1].ToString());
            }
        }

        Console.Write(output.ToString());
    }

