using System;
using System.IO;
using System.Text;

public class Program
{
    private const int Shift = 20;
    private const long Mask = (1L << Shift) - 1;

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());
        int testCases = scanner.NextInt();
        var output = new StringBuilder();

        for (int test = 0; test < testCases; test++)
        {
            int n = scanner.NextInt();
            int k = scanner.NextInt();

            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = scanner.NextInt();

            long[] items = new long[n];
            for (int i = 0; i < n; i++)
            {
                int b = scanner.NextInt();
                items[i] = ((long)a[i] << Shift) | (uint)b;
            }

            Array.Sort(items);

            int[] maxHeap = new int[k];
            int heapSize = 0;
            long sum = 0;
            long answer = long.MaxValue;

            for (int i = 0; i < n; i++)
            {
                int currentA = (int)(items[i] >> Shift);
                int currentB = (int)(items[i] & Mask);

                if (heapSize < k)
                {
                    sum += currentB;
                    Push(maxHeap, ref heapSize, currentB);
                }
                else if (currentB < maxHeap[0])
                {
                    sum += currentB - maxHeap[0];
                    maxHeap[0] = currentB;
                    SiftDown(maxHeap, heapSize, 0);
                }

                if (heapSize == k)
                {
                    long value = (long)currentA * sum;
                    if (value < answer)
                        answer = value;
                }
            }

            output.Append(answer).Append('\n');
        }

        Console.Write(output.ToString());
    }

    private static void Push(int[] heap, ref int size, int value)
    {
        int index = size++;
        while (index > 0)
        {
            int parent = (index - 1) >> 1;
            if (heap[parent] >= value)
                break;

            heap[index] = heap[parent];
            index = parent;
        }
        heap[index] = value;
    }

    private static void SiftDown(int[] heap, int size, int index)
    {
        int value = heap[index];

        while (true)
        {
            int left = (index << 1) + 1;
            if (left >= size)
                break;

            int right = left + 1;
            int largerChild = left;

            if (right < size && heap[right] > heap[left])
                largerChild = right;

            if (heap[largerChild] <= value)
                break;

            heap[index] = heap[largerChild];
            index = largerChild;
        }

        heap[index] = value;
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
