public static class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        int[] head = new int[n];
        Array.Fill(head, -1);

        int[] to = new int[2 * (n - 1)];
        int[] next = new int[2 * (n - 1)];
        int[] degree = new int[n];

        int edgeIndex = 0;
        for (int i = 0; i < n - 1; i++)
        {
            int u = scanner.NextInt() - 1;
            int v = scanner.NextInt() - 1;

            to[edgeIndex] = v;
            next[edgeIndex] = head[u];
            head[u] = edgeIndex++;

            to[edgeIndex] = u;
            next[edgeIndex] = head[v];
            head[v] = edgeIndex++;

            degree[u]++;
            degree[v]++;
        }

        bool[] visited = new bool[n];
        int[] stack = new int[n];
        long answer = 0;

        for (int start = 0; start < n; start++)
        {
            if (degree[start] != 3 || visited[start])
                continue;

            int stackSize = 0;
            stack[stackSize++] = start;
            visited[start] = true;

            long boundaryDegreeTwoVertices = 0;

            while (stackSize > 0)
            {
                int vertex = stack[--stackSize];

                for (int e = head[vertex]; e != -1; e = next[e])
                {
                    int neighbor = to[e];

                    if (degree[neighbor] == 2)
                    {
                        boundaryDegreeTwoVertices++;
                    }
                    else if (degree[neighbor] == 3 && !visited[neighbor])
                    {
                        visited[neighbor] = true;
                        stack[stackSize++] = neighbor;
                    }
                }
            }

            answer += boundaryDegreeTwoVertices *
                      (boundaryDegreeTwoVertices - 1) / 2;
        }

        Console.WriteLine(answer);
    }
}
