using System;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do { c = ReadByte(); } while (c <= 32);

            int value = 0;
            while (c > 32)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }

        public string Next()
        {
            int c;
            do { c = ReadByte(); } while (c <= 32);

            char[] chars = new char[1024];
            int count = 0;

            while (c > 32)
            {
                if (count == chars.Length)
                    Array.Resize(ref chars, chars.Length * 2);

                chars[count++] = (char)c;
                c = ReadByte();
            }

            return new string(chars, 0, count);
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int h = scanner.NextInt();
        int w = scanner.NextInt();
        int d = scanner.NextInt();
        int n = h * w;

        byte[] grid = new byte[n];
        int[] distance = new int[n];
        int[] queue = new int[n];

        for (int i = 0; i < n; i++)
            distance[i] = -1;

        int head = 0;
        int tail = 0;

        for (int row = 0; row < h; row++)
        {
            string line = scanner.Next();
            int offset = row * w;

            for (int col = 0; col < w; col++)
            {
                int index = offset + col;
                grid[index] = (byte)line[col];

                if (line[col] == 'H')
                {
                    distance[index] = 0;
                    queue[tail++] = index;
                }
            }
        }

        int answer = tail;

        while (head < tail)
        {
            int current = queue[head++];
            int currentDistance = distance[current];

            if (currentDistance >= d)
                continue;

            int nextDistance = currentDistance + 1;
            int column = current % w;

            if (current >= w)
                Visit(current - w, nextDistance, grid, distance, queue, ref tail, ref answer);

            if (current + w < n)
                Visit(current + w, nextDistance, grid, distance, queue, ref tail, ref answer);

            if (column > 0)
                Visit(current - 1, nextDistance, grid, distance, queue, ref tail, ref answer);

            if (column + 1 < w)
                Visit(current + 1, nextDistance, grid, distance, queue, ref tail, ref answer);
        }

        Console.WriteLine(answer);
    }

    private static void Visit(
        int index,
        int newDistance,
        byte[] grid,
        int[] distance,
        int[] queue,
        ref int tail,
        ref int answer)
    {
        if (grid[index] == (byte)'#' || distance[index] != -1)
            return;

        distance[index] = newDistance;
        queue[tail++] = index;
        answer++;
    }
}
