        }
        else
        {
            int middle = (n + 1) / 2;

            for (int i = 0; i < k; i++)
                append(middle);
            counts[middle] = 0;

            append(middle - 1);
            counts[middle - 1]--;

            for (int value = n; value >= 1; value--)
            {
                for (int j = 0; j < counts[value]; j++)
                    append(value);
            }
