using System;
using System.IO;

public class Program
{
    private class Node
    {
        public Node Zero;
        public Node One;
        public int Count;
        public int Dp0;
        public int Dp1;
    }

    private static void Insert(Node root, long value)
    {
        Node node = root;
        node.Count++;

        for (int bitIndex = 0; bitIndex < 64; bitIndex++)
        {
            int bit = (int)((value >> bitIndex) & 1L);

            if (bit == 0)
            {
                if (node.Zero == null)
                    node.Zero = new Node();
                node = node.Zero;
            }
            else
            {
                if (node.One == null)
                    node.One = new Node();
                node = node.One;
            }

            node.Count++;
        }
    }

    private static void Solve(Node node)
    {
        if (node == null)
            return;

        if (node.Count == 1)
        {
            node.Dp0 = 1;
            node.Dp1 = 1;
            return;
        }

        Solve(node.Zero);
        Solve(node.One);

        for (int currentBit = 0; currentBit <= 1; currentBit++)
        {
            Node active = currentBit == 0 ? node.Zero : node.One;
            Node sibling = currentBit == 0 ? node.One : node.Zero;
            int siblingBit = 1 - currentBit;
            int best = 0;

            for (int nextBit = 0; nextBit <= 1; nextBit++)
            {
                int value = 0;

                if (active != null)
                    value += nextBit == 0 ? active.Dp0 : active.Dp1;

                if (sibling != null)
                {
                    int requiredSiblingNextBit =
                        nextBit ^ siblingBit ^ 1;

                    Node matching = requiredSiblingNextBit == 0
                        ? sibling.Zero
                        : sibling.One;

                    if (matching != null)
                        value += matching.Count;
                }

                if (value > best)
                    best = value;
            }

            if (currentBit == 0)
                node.Dp0 = best;
            else
                node.Dp1 = best;
        }
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        int n = (int)scanner.NextLong();
        Node root = new Node();

        for (int i = 0; i < n; i++)
        {
            long a = scanner.NextLong();
            Insert(root, -a);
        }

        Solve(root);
        Console.WriteLine(Math.Max(root.Dp0, root.Dp1));
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;

                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            bool negative = false;
            if (c == '-')
            {
                negative = true;
                c = Read();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return negative ? -value : value;
        }
    }
