    {
        var scanner = new FastScanner(Console.OpenStandardInput());
        int n = scanner.NextInt();

        int[] left = new int[n + 1];
        int[] right = new int[n + 1];
        int root = 0;

        for (int i = 1; i <= n; i++)
        {
            int parent = scanner.NextInt();

            if (parent == 0)
            {
                left[i] = root;
                root = i;
            }
            else
            {
                left[i] = right[parent];
                right[parent] = i;
            }
        }

        int[] stack = new int[n];
        int[] order = new int[n];
        int stackSize = 0;
        int orderSize = 0;

        stack[stackSize++] = root;

        while (stackSize > 0)
        {
            int node = stack[--stackSize];
            order[orderSize++] = node;

            if (left[node] != 0)
                stack[stackSize++] = left[node];
            if (right[node] != 0)
                stack[stackSize++] = right[node];
        }

        int[] subtreeSize = new int[n + 1];
        long sizeProduct = 1;

        for (int i = orderSize - 1; i >= 0; i--)
        {
            int node = order[i];
            subtreeSize[node] = 1 + subtreeSize[left[node]] + subtreeSize[right[node]];
            sizeProduct = sizeProduct * subtreeSize[node] % Mod;
        }

        long factorial = 1;
        for (int i = 2; i <= n; i++)
            factorial = factorial * i % Mod;

        long answer = factorial * ModPow(sizeProduct, Mod - 2) % Mod;
        Console.WriteLine(answer);
