using System;
using System.IO;

public class Program
{
    const long Mod = 998244353;

    public static void Main()
    {
        FastScanner fs = new FastScanner(Console.OpenStandardInput());

        int n = fs.NextInt();
        int m = fs.NextInt();
        int k = fs.NextInt();

        int[] x = new int[m];
        for (int i = 0; i < m; i++)
            x[i] = fs.NextInt();

        int changes = 0;
        for (int i = 0; i + 1 < m; i++)
        {
            if (x[i] != x[i + 1])
                changes++;
        }

        int minimumLength = m * k - 1 + changes;
        int degree = n - minimumLength;

        if (degree < 0)
        {
            Console.WriteLine(0);
            return;
        }

        int q = k - 1;

        long factorial = 1;
        for (int i = 1; i <= q; i++)
            factorial = factorial * i % Mod;

        long multiplier = ModPow(factorial, m);

        // We need the coefficient of z^degree in
        // product_{i=1}^{q} (1 - i*z)^(-m)
        // times (1 - (q-1)*z)^(-changes).
        //
        // If P(z) = sum p_n z^n and
        // s_j = m * sum_{i=1}^{q} i^j + changes * (q-1)^j,
        // then n*p_n = sum_{j=1}^{n} s_j*p_{n-j}.
        long[] powerSums = new long[degree + 1];

        for (int value = 1; value <= q; value++)
        {
            long power = 1;
            for (int j = 1; j <= degree; j++)
            {
                power = power * value % Mod;
                powerSums[j] = (powerSums[j] + (long)m * power) % Mod;
            }
        }

        if (changes > 0)
        {
            int value = q - 1;
            long power = 1;
            for (int j = 1; j <= degree; j++)
            {
                power = power * value % Mod;
                powerSums[j] = (powerSums[j] + (long)changes * power) % Mod;
            }
        }

        long[] inverse = new long[degree + 1];
        if (degree >= 1)
        {
            inverse[1] = 1;
            for (int i = 2; i <= degree; i++)
                inverse[i] = Mod - (Mod / i) * inverse[Mod % i] % Mod;
        }

        long[] coefficients = new long[degree + 1];
        coefficients[0] = 1;

        for (int i = 1; i <= degree; i++)
        {
            long sum = 0;
            for (int j = 1; j <= i; j++)
                sum = (sum + powerSums[j] * coefficients[i - j]) % Mod;

            coefficients[i] = sum * inverse[i] % Mod;
        }

        long answer = multiplier * coefficients[degree] % Mod;
        Console.WriteLine(answer);
    }

    static long ModPow(long value, int exponent)
    {
        long result = 1;
        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * value % Mod;
            value = value * value % Mod;
            exponent >>= 1;
        }
        return result;
    }

