using System;
using System.IO;

public class Program
{
    const int Mod = 998244353;

    public static void Main()
    {
        FastScanner fs = new FastScanner(Console.OpenStandardInput());
        int n = fs.NextInt();
        int k = fs.NextInt();
        string s = fs.Next();

        int d = n + 2;
        int stateCount = d * d * d * 4;

        int[] dp = new int[stateCount];
        int[] next = new int[stateCount];

        // Before reading any characters, prefix state 0 has been visited once.
        dp[0] = 1;

        int[] countIncrement = new int[4];
        countIncrement[0] = 0;
        countIncrement[1] = d * d * 4;
        countIncrement[2] = d * 4;
        countIncrement[3] = 4;

        for (int pos = 0; pos < n; pos++)
        {
            Array.Clear(next, 0, next.Length);

            int fixedMove;
            if (s[pos] == 'A') fixedMove = 1;
            else if (s[pos] == 'B') fixedMove = 2;
            else if (s[pos] == 'C') fixedMove = 3;
            else fixedMove = 0;

            int visited = pos + 1;

            for (int c1 = 0; c1 <= visited; c1++)
            {
                for (int c2 = 0; c1 + c2 <= visited; c2++)
                {
                    int maxC3 = visited - c1 - c2;
                    for (int c3 = 0; c3 <= maxC3; c3++)
                    {
                        int baseIndex = ((c1 * d + c2) * d + c3) * 4;

                        for (int current = 0; current < 4; current++)
                        {
                            int value = dp[baseIndex + current];
                            if (value == 0) continue;

                            if (fixedMove != 0)
                            {
                                int target = current ^ fixedMove;
                                Add(next, baseIndex + countIncrement[target] + target, value);
                            }
                            else
                            {
                                for (int move = 1; move <= 3; move++)
                                {
                                    int target = current ^ move;
                                    Add(next, baseIndex + countIncrement[target] + target, value);
                                }
                            }
                        }
                    }
                }
            }

            int[] temp = dp;
            dp = next;
            next = temp;
        }

        int answer = 0;
        int totalVisits = n + 1;

        for (int c1 = 0; c1 <= totalVisits; c1++)
        {
            for (int c2 = 0; c1 + c2 <= totalVisits; c2++)
            {
                int maxC3 = totalVisits - c1 - c2;
                for (int c3 = 0; c3 <= maxC3; c3++)
                {
                    int c0 = totalVisits - c1 - c2 - c3;
                    int goodCount =
                        c0 * (c0 - 1) / 2 +
                        c1 * (c1 - 1) / 2 +
                        c2 * (c2 - 1) / 2 +
                        c3 * (c3 - 1) / 2;

                    if (goodCount < k) continue;

                    int baseIndex = ((c1 * d + c2) * d + c3) * 4;
                    for (int current = 0; current < 4; current++)
                    {
                        Add(ref answer, dp[baseIndex + current]);
                    }
                }
            }
        }

        Console.WriteLine(answer);
    }

    static void Add(int[] array, int index, int value)
    {
        int sum = array[index] + value;
        if (sum >= Mod) sum -= Mod;
        array[index] = sum;
    }

    static void Add(ref int target, int value)
    {
        int sum = target + value;
        if (sum >= Mod) sum -= Mod;
        target = sum;
    }

    sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int pointer;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int ReadByte()
        {
            if (pointer >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                pointer = 0;
                if (length == 0) return -1;
            }
            return buffer[pointer++];
        }

        public string Next()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            char[] chars = new char[64];
            int count = 0;

            while (c > 32 && c != -1)
            {
                if (count == chars.Length)
                    Array.Resize(ref chars, chars.Length * 2);
                chars[count++] = (char)c;
                c = ReadByte();
            }

            return new string(chars, 0, count);
        }

        public int NextInt()
        {
            string token = Next();
            return int.Parse(token);
        }
    }
}
